quests[10762] = { id = 10762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Dumphry", description = "The symbol on the key's handle... it is hard to make it out inside the mold, but I recognize it at the Shattered Hand's own.\n\nThere is a good chance this key will allow you to enter the Shattered Halls.\n\nSpeak to Dumphry.  He is a master of his craft.  If he can't craft this key for you, no one can.", sourceObjective = "Bring the Primed Key Mold to Dumphry in Honor Hold.", progress = "What is this?", completion = "A key?  Danath should have us working on siege engines!", sourceObjectiveStatus = "unverified-source-field" }
quests[10763] = { id = 10763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dumphry's Request", description = "Fel orcs might be complete barbarians but their smithing is not as primitive as you might think.  Only fel iron can be used with this mold if we want to end up with a working key - anything else would probably end up breaking it.\n\nBring me some fel iron bars, a bit of arcane dust and motes of fire.  I'll try my hand at it, but I make no promises.", sourceObjective = "Bring 4 Fel Iron Bars, 2 Arcane Dust and 4 Motes of Fire to Dumphry at Honor Hold in Hellfire Peninsula.", progress = "Have you obtained the materials I requested?", completion = "Let's try it then.  Let's see what fel orc crafting is all about.", sourceObjectiveStatus = "unverified-source-field" }
quests[10764] = { id = 10764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hotter than Hell", description = "It's not working, <lad/lass>.  I cannot give it enough heat... the materials will not be properly tempered.\n\nYou know, the Fel Reavers used by the Burning Legion are powered by a scalding core of fel fire - it burns much hotter than normal fire.\n\nIf you could find enough people to take one down, you could heat the mold in the insides of the fallen reaver.  Beware, {class}, those fel reavers pack quite a punch.", sourceObjective = "Destroy a Fel Reaver in Hellfire Peninsula and plunge the Unfired Key Mold into its remains. Bring the Charred Key Mold to Dumphry in Honor Hold.", progress = "Did you do what I asked of you, {class}?", completion = "You've done it, laddie!  Only thing left to do is for you to take it to Hellfire Citadel and kill yourself some orcs!", sourceObjectiveStatus = "unverified-source-field" }
quests[10765] = { id = 10765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Worlds Collide...", description = "At the southern end of the Path of Conquest, near a stationary caravan, I discovered what looked like a meeting between a giant and a blood elf chancellor. You've probably already noticed the smaller giants on the path as well. Something is just not right about all of this, grunt.\n\nI want you to fight your way to this meeting and break up the party. Recover whatever you can from the scene and then call for one of us with the flare gun.", sourceObjective = "Slay Chancellor Bloodleaf and Corok the Mighty and recover Illidan's Command.", progress = "What have you to report, soldier?", completion = "So they are attempting to gain the favor of the giants, eh? I have a plan that promises to sever this unholy union.", sourceObjectiveStatus = "unverified-source-field" }
quests[10766] = { id = 10766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion Point: Cataclysm", description = "Now that we have access to the Legion's base at Invasion Point: Cataclysm, we need to figure out a way to shut down their operations there. Wildhammer Stronghold won't be safe until the Legion's presence is erased from Shadowmoon Valley.\n\nI've sent an advance party up to the invasion point to help you formulate a plan to destroy the Legion's supplies. Go back to Legion Hold and step into the teleporter with the green crystals above it. Plexi will meet you at your destination.", sourceObjective = "Report to Plexi at Invasion Point: Cataclysm.", completion = "Pleased to meet you, {name}. Name's Plexi.\n\nI won't bore you with formalities. We both know why we're here. Now, let's get to work.", sourceObjectiveStatus = "unverified-source-field" }
quests[10767] = { id = 10767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion Point: Cataclysm", description = "Now that we have access to the Legion's base at Invasion Point: Cataclysm, we need to figure out a way to shut down their operations there. Shadowmoon Village won't be safe until the Legion's presence is erased from the valley.\n\nI've sent an advance party up to the invasion point to help you formulate a plan to destroy the Legion's supplies. Go back to Legion Hold and step into the teleporter with the green crystals above it. Nakansi will meet you at your destination.", sourceObjective = "Report to Nakansi at Invasion Point: Cataclysm.", completion = "You must be the {race} Blood Guard Gulmok told me to expect. I have a plan in mind, but I'll need your help to complete the preparations.", sourceObjectiveStatus = "unverified-source-field" }
quests[10768] = { id = 10768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabards of the Illidari", description = "The wind riders must return to Shadowmoon Village to prepare for the next phase of our assault. What I need from you now are the tabards that these blood elves wear.\n\nWhen you have collected enough tabards, call for a wind rider using the Kor'kron flare gun. Prepare yourself for a bit of espionage, {race}!", sourceObjective = "Collect 10 Illidari Tabards.", progress = "What have you to report, soldier?", completion = "Ah-ha! These will do quite nicely.", sourceObjectiveStatus = "unverified-source-field" }
quests[10769] = { id = 10769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dissension Amongst the Ranks...", description = "Researcher Tiorus was kind enough to put this concoction together for the final strike. I merely pour it upon this tabard that you have provided for me and the item is imbued with the essence of the Illidari filth.\n\nTake the enchanted tabard and travel to the Eclipsion Fields, southwest of Eclipse Point. Once there, use the tabard to transform into an agent of Illidan. While in disguise, slay the crazed colossi that wander the field. They will think it an attack by the Eclipsion and sever all ties!", sourceObjective = "Slay 5 Crazed Colossus while in disguise as an Illidari blood elf and return to Overlord Or'barokh at Shadowmoon Village in Shadowmoon Valley. He will also want his Kor'kron Flare Gun returned.", progress = "You have returned!", completion = "Well, well, well... If it isn't the grunt I sent out into the field. You're back and in one piece.\n\n<Or'barokh nods.>\n\nI knew you wouldn't let me down, soldier. You've stopped a major Illidari advance and, in doing so, earned yourself a little reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[10770] = { id = 10770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Little Embers", description = "Northeast of here, on the plateau above us lies the burnt ashes of my ancient home. A great wood flourished there before the Burning Legion sent their imps to burn us away. So many died that even centuries later my tired old heart hungers for revenge. There are too many of them for us to ever reclaim the land, but you could make them afraid.\n\nSurely you will help me?", sourceObjective = "Mosswood the Ancient wants you to kill 8 Scorch Imps and then return to him in Ruuan Weald.", progress = "Soon I will sleep the deep sleep of the forest. Before I dig my roots deep and close these old eyes forever, I hope to know that those wretched imps suffered and perished.", completion = "There are so many that we could never kill them all, but you have given me hope. Perhaps I shall try harder for the next few centuries to revive my beloved wood.", sourceObjectiveStatus = "unverified-source-field" }
quests[10771] = { id = 10771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From the Ashes", description = "If you follow the road east and up the side of the mountain, then turn north, you will come to my long lost home.\n\nOnce there was a wood there. Its name is forgotten. Long ago the Burning Legion summoned scorched imps and other creatures of flame. My home was destroyed and my people fled. Now only I remain. \n\nI have saved some ironroot seeds that could be planted in fertile volcanic soil. Their magic is strong. Do this for me and I will share with you the treasures of a forgotten age.", sourceObjective = "Mosswood the Ancient wants you to journey to Skald and plant Ironroot Seeds in three different mounds of Fertile Volcanic Soil and then return to him in Ruuan Weald.", progress = "Is it done?  Did you return some life to my ancient home?", completion = "You destroyed many of those foul little creatures.  I can rest easier in that knowledge.", sourceObjectiveStatus = "unverified-source-field" }
quests[10772] = { id = 10772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of Conquest", description = "My gryphon riders have come back with a bit of news! The Eclipsion blood elves are planning something big. They've begun forming their armies at the Path of Conquest, located east of here - adjacent to Eclipse Point.\n\nI want you to travel to the Path of Conquest and assess the situation. Once you've done so, use this flare gun to signal a gryphon rider. One will swoop down from the sky to meet you. Tell 'em what you've discovered and they'll give you the next set of orders.", sourceObjective = "Travel to the Path of Conquest in Shadowmoon Valley.", progress = "What have you to report, soldier?", completion = "Indeed, these troublesome whelps are up to something insidious. We must investigate further...", sourceObjectiveStatus = "unverified-source-field" }
quests[10773] = { id = 10773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaching the Path", description = "We're going to need more time, {race}. I'm going to fly further ahead with some of the other gryphon riders. Hopefully, we can gather some more information. What I need from you now is to clear a path and more importantly, keep their arrows pointed away from us!\n\nCall for a gryphon rider with the Wildhammer flare gun once you have thinned their numbers.", sourceObjective = "Slay 20 Eclipsion Soldiers, 10 Eclipsion Cavaliers, and 5 Sons of Corok.", progress = "What have you to report, soldier?", completion = "You won't believe this, soldier!", sourceObjectiveStatus = "unverified-source-field" }
quests[10774] = { id = 10774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Elf + Giant = ???", description = "At the southern end of the Path of Conquest, near a stationary caravan, I discovered what looked like a meeting between a giant and a blood elf chancellor. What are giants even doing here? Something is just not right about all of this, grunt.\n\nI want you to fight your way to this meeting and break up the party. Recover whatever you can from the scene and then call for one of us with the flare gun.", sourceObjective = "Slay Chancellor Bloodleaf and Corok the Mighty and recover Illidan's Command.", progress = "What have you to report, soldier?", completion = "So they are attempting to gain the favor of the giants, eh? I have a plan that could serve to sever this unholy union.", sourceObjectiveStatus = "unverified-source-field" }
quests[10775] = { id = 10775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabards of the Illidari", description = "The gryphon riders must return to Wildhammer Stronghold to prepare for the next phase of our assault. What I need from you now are the tabards that these blood elves wear.\n\nWhen you have collected enough tabards, call for a gryphon rider using the Wildhammer flare gun. Prepare yourself for a bit of espionage, {race}!", sourceObjective = "Collect 10 Illidari Tabards.", progress = "What have you to report, soldier?", completion = "Ah-ha! These will do quite nicely.", sourceObjectiveStatus = "unverified-source-field" }
quests[10776] = { id = 10776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dissension Amongst the Ranks...", description = "Gnomus was kind enough to put this concoction together for the final strike. I merely pour it upon this tabard that you have provided for me and the item is imbued with the essence of the Illidari filth.\n\nTake the enchanted tabard and travel to the Eclipsion Fields, southwest of Eclipse Point. Once there, use the tabard to transform into an agent of Illidan. While in disguise, slay the crazed colossi that wander the field. They will think it an attack by the Eclipsion and sever all ties!", sourceObjective = "Slay 5 Crazed Colossus while in disguise as an agent of Illidan and return to Thane Yoregar at Wildhammer Stronghold in Shadowmoon Valley. He will also want his Wildhammer Flare Gun returned.", progress = "You have returned!", completion = "Well, well, well... If it isn't the soldier I sent out into the field. You're back and in one piece.\n\n<Yoregar nods.>\n\nI knew you wouldn't let me down, soldier. You've stopped a major Illidari advance and, in doing so, earned yourself a little reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[10777] = { id = 10777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asghar's Totem", description = "What you read in the commander's journal is true. While the orcish Horde massed under Gul'dan, my people sought to defend ourselves from the threat by striking against him. Gul'dan learned of their intentions and cast a mighty spell that destroyed our camps and twisted the spirits of my brothers.\n\nThey must be stopped before they unleash a greater evil. In the Sketh'lon Wreckage to the north, seek out Asghar and bring me the totem he carries. With it, we can begin to thwart the dark conclave's plans.", sourceObjective = "Bring the Sketh'lon War Totem to Parshah in the Magma Fields.", progress = "Have you recovered the totem from Asghar?", completion = "<Parshah examines the totem.>\n\nGood. This old totem hasn't lost its power over the years, but it alone is not enough to stop the dark conclave.", sourceObjectiveStatus = "unverified-source-field" }
quests[10778] = { id = 10778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rod of Lianthe", description = "The totem alone is not strong enough to counteract the sinister magics of the dark conclave.\n\nWe can combine it with other objects of power, forming a staff to focus the energies. We cannot rescue my brethren from the depths of their depravity, but we can stop them.\n\nOne of the items I need for the staff is the Rod of Lianthe, held by the blood elves at Eclipse Point to the southeast. It is kept in a pavilion on the top tier of the ruins and will be heavily guarded. Use caution, {name}.", sourceObjective = "Obtain Lianthe's Key from any of the blood elves at Eclipse Point and use it to open Lianthe's Strongbox and claim the Rod of Lianthe. Return the rod to Parshah in the Magma Fields.", progress = "Did you manage to get the rod?", completion = "Well done. Such a treasure deserves better than to be shut away in a dark chest. We shall see it used for a worthy purpose.", sourceObjectiveStatus = "unverified-source-field" }
quests[10779] = { id = 10779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter's Path", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Huntress Kella Nightbow at LOCATION. She can put you on the path to earning a pet of your own.", sourceObjective = "Speak with Huntress Kella Nightbow at LOCATION.", sourceObjectiveStatus = "unverified-source-field" }
quests[10780] = { id = 10780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sketh'lon Feathers", description = "There is one last element missing from the staff. We must direct the staff's power toward the Dark Conclave spirits.\n\nWe can do that by gathering feathers scattered on the ground at the Sketh'lon Base Camp and using them in the staff. The base camp is to the south, east of Wildhammer Stronghold.\n\nGul'dan's magic utterly destroyed my brethren, leaving only their spirits, but it did not stop there. The magic fed on the spell the arakkoa were preparing, forging a sinister force that engulfed the spirits.", sourceObjective = "Gather 8 Sketh'lon Feathers and bring them to Parshah in the Magma Fields.", progress = "Have you gathered the feathers for the staff?", completion = "<Parshah accepts the ash-dusted feathers, shaking his head.>\n\nIt would've been better if they had died that day, but nothing is ever that simple. That Gul'dan's magic would turn them into the kind of threat they tried to stop is a particularly cruel twist of fate.", sourceObjectiveStatus = "unverified-source-field" }
quests[10781] = { id = 10781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle of the Crimson Watch", description = "They are probably searching for you on the Path of Conquest as we speak. You must make your escape, {race}!\n\nLeave me, I'm done for... They... I think I hear them coming. It's now or never! Get out! If you choose to stay, you will have to fight!\n\nIf you fight and somehow manage to survive, take what you have learned here and deliver that knowledge to A'dal in Shattrath City.", sourceObjective = "Battle the forces of Illidan at Crimson Watch and survive!\n\nReturn to A'dal at Shattrath City should you emerge the victor.", progress = "<A'dal greets you.>", completion = "This Crimson Sigil will be investigated. They pose a threat to all life on Draenor. I foresee a day when their dark master has to answer for his crimes. Perhaps it will be you who brings him to justice, hero.", sourceObjectiveStatus = "unverified-source-field" }
quests[10782] = { id = 10782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imbuing the Headpiece", description = "The staff is nearly finished!\n\nAll that remains is to imbue the headpiece with power flowing from the echoes of Gul'dan in this accursed place. To the east, near the Fel Pits and south of the Deathforge, is the Altar of Damnation.\n\nThere, fragments of Gul'dan's past are trapped. When you carry the unfinished headpiece of the staff into the area around the altar, don't be surprised if some of the entities react to it. You will be carrying a dangerous object with strong connections to the cataclysm.", sourceObjective = "Equip the Unfinished Headpiece, travel to the Altar of Damnation, and use it while standing near Gul'dan. When the headpiece is energized, return to Parshah in the Magma Fields.", progress = "Have you returned with the imbued headpiece?", completion = "<Parshah accepts the headpiece, handing it gingerly.>\n\nThis holds the power that we'll need to disrupt the dark conclave's efforts in the Sketh'lon Base Camp.", sourceObjectiveStatus = "unverified-source-field" }
quests[10783] = { id = 10783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron Sablemane", description = "Here is my plan. We will poison the ogres and then destroy their gronn master.\n\nDuring my travels in these mountains, I met a man named Baron Sablemane. He is a master of the alchemical arts, and may be convinced to assist us.\n\nYou will find him at the Circle of Blood, down in the canyon to the north of here. Whatever price he requires, I will leave it to your discretion to accept.", sourceObjective = "Speak with Baron Sablemane at the Circle of Blood in the Blade's Edge Mountains.", completion = "Hello, {race}. I am Baron Sablemane. A friend of Rexxar's is a friend of mine.", sourceObjectiveStatus = "unverified-source-field" }
quests[10784] = { id = 10784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crush the Bloodmaul Camp", description = "<Tor'chunk leans in close to whisper.>\n\n{name}, you've done us more than proud in the fight against the ogres so far.  And while I have every confidence in what Rexxar has planned, I would still ask that you crush the ogres at Bloodmaul Camp before returning.\n\nThat way we'll be doubly certain of the outcome.\n\nTo get there, head north down the ramp out of Thunderlord.  Then, at the base of the ramp, head west across Dragons' End and north through the Churning Gulch and Daggermaw Canyon.", sourceObjective = "Slay 10 Bloodmaul Maulers and 5 Bloodmaul Warlocks.", completion = "<Tor'chunk nods his head in obvious approval of your killing prowess.>\n\nYou continue to impress me, {name}.  Every time one of those stinking ogres is felled, we come one step closer to ridding ourselves of an unworthy foe.", sourceObjectiveStatus = "unverified-source-field" }
quests[10785] = { id = 10785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's a Trap!", description = "There's is no cause of fury greater in this world than that of Gruul and his sons. They slaughtered my people - my children - and now I will have revenge.\n\nI have fashioned a trap from dragon fire, and if you're clever enough, you can use it to kill even a gronn.\n\nJust hurry, take the trap to Rexxar. My thirst for revenge must be quenched.", sourceObjective = "Deliver the Dragonfire Trap to Rexxar at Thunderlord Stronghold in the Blade's Edge Mountains.", progress = "Did you recover whatever was in that gronn's sack for Sablemane? What has he given us?", completion = "Hmm, a trap fashioned from the essence of dragon fire? I wonder how Sablemane comes by such rarified substances?\n\nIt does not matter. What does matter is that we are going to use it to slay a son of Gruul.", sourceObjectiveStatus = "unverified-source-field" }
quests[10786] = { id = 10786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slaughter at Boulder'mok", description = "I know that Rexxar has plans for you to head to Boulder'mok.  I have something that I want you to do while you are there.\n\nWe must take any chance we can get to strike down the ogres of these mountains, or they will overrun us, and all that we have bled and died for will be for nothing!\n\nBoulder'mok lies far to the northwest.  Travel north to Ruuan Weald, and from there head west through the tunnel and past the Raven's Wood.\n\n{name}, I want you to kill the Bladespire ogres of Boulder'mok.  Wipe them out!", sourceObjective = "Slay 5 Boulder'mok Brutes and 3 Boulder'mok Shaman, and then return to Tor'chunk Twoclaws at Thunderlord Stronghold in the Blade's Edge Mountains.", completion = "<Tor'chunk grins at the story that you tell him about your adventures at Boulder'mok.>\n\nAh, I wish that I could have been there with you.  Let me tell you something, {name}: never accept any duty that keeps you from the glory of battle!\n\nHah!  After all of the ogre killing that you've done, are there any still left in these mountains for me?!", sourceObjectiveStatus = "unverified-source-field" }
quests[10788] = { id = 10788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Talionia", description = "One of your masters, Talionia, in Silvermoon City has sent a summons for you, {name}.  I'm certain it is time you learned to summon and control a more powerful demon, so I suggest you see her at once.  I understand Talionia is found in The Sanctum, a cozy little den of evil found along Murder Row.", sourceObjective = "Speak with Talionia in Silvermoon City.", completion = "So the world traveler returns...\n\nI hope my sarcasm is evident, {name}, for you have inconvenienced me greatly by forcing me to send out a summons.  Consider that you are but a felguard's hair away from incineration, and they don't have any hair.\n\nPay attention closely, this is not a lesson you'll get twice.", sourceObjectiveStatus = "unverified-source-field" }
quests[10789] = { id = 10789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Carendin Halgar", description = "Ah, so there you are, {name}.\n\nCarendin Halgar has sent out word for you to come see him in the Magic Quarter of Undercity.  He is not known for his patience, so I would not wait long.", sourceObjective = "Speak with Carendin Halgar in Undercity.", completion = "Yes, I can see it in your eye sockets.  You are eager to learn more.\n\nVery well, this is a lesson we'll both enjoy.", sourceObjectiveStatus = "unverified-source-field" }
quests[10790] = { id = 10790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Gan'rul Bloodeye", description = "You are a long way from home, {race}.  Perhaps it is time you returned to learn from your master, Gan'rul Bloodeye.  His knowledge is known to all of our craft, even those of us here.\n\nGan'rul dwells in the Cleft of Shadow in Orgrimmar.", sourceObjective = "Speak with Gan'rul Bloodeye in Orgrimmar.", completion = "It is the forbidden knowledge you hunger for, is it?  I can give you that...", sourceObjectiveStatus = "unverified-source-field" }
quests[10791] = { id = 10791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcoming the Wolf Spirit", description = "I've nearly completed the vestments that I'll wear during the ceremony. As I add the finishing touches, I'd like you to set this incense by the candles near the runestone to my left.\n\nI believe it will help us to attract the wolf spirit's attention, since it was made in the days of the orcish clans. I can almost imagine my ancestors using it in a ceremony paying tribute to the wolf spirit after a successful hunt.\n\nOnce you've placed the incense, I'll begin the ceremony.", sourceObjective = "Use the Ceremonial Incense near the candles in Malukaz's hut and observe the ceremony. When the ceremony is complete, speak with Malukaz again.", progress = "Reestablishing ties with the wolf spirit is just the beginning of my journey, not the end.", completion = "This is incredible! I set out on this journey unsure of whether the wolf spirit would answer our summons and now it feels as though he's always been here. Perhaps he was, {name}.\n\nPerhaps he was waiting for the orcs to realize what their choices had wrought.", sourceObjectiveStatus = "unverified-source-field" }
quests[10792] = { id = 10792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeth'Gor Must Burn!", description = "The Bleeding Hollow clan have betrayed their noble heritage!  We, the orcs who fought and died to save ourselves from the fel taint of Mannoroth, look upon our vile cousins and see only weakness and ignobility... and for that, they must burn!\n\nEnter Zeth'Gor, their bastion to the east, and burn their buildings.  Kill peons for their torches, ignite them at their forge, and hurl the burning torches at their hovels, their stable and their barracks.  Burn them all, and then return to me!\n\nFor the Horde!", sourceObjective = "Kill Bleeding Hollow Peons for their torches, ignite them at Zeth'Gor's forge then throw the burning torches at Zeth'Gor Buildings.", progress = "Zeth'Gor must burn, {name}!  Speak with me again when your task is complete.", completion = "Hah!  I could see the smoke and flames of Zeth'Gor from here!  May the Bleeding Hollow fiends burn to ash and drift far from the sight of any true orc!\n\nThank you, {name}.  You helped burn away an afront to every orc's spirit.", sourceObjectiveStatus = "unverified-source-field" }
quests[10793] = { id = 10793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Journal of Val'zareq: Portends of War", description = "This journal documents the recent activities of Illidan's armies. It also explains why Val'zareq was parading around the Path of Conquest. He was personally responsible for the capture of a high general of the Sha'tar.\n\nThis general is being held at a post known as Crimson Watch, located at the southern end of the Path of Conquest. A mysterious faction, calling itself the Crimson Sigil, is charged with his incarceration. If you choose to investigate, it would be wise to bring allies.", sourceObjective = "Locate Marcus Auralion, High General of the Sha'tar, at Crimson Watch.\n\nLook for him inside a crystalline prison.", progress = "<General Auralion is floating in the middle of the crystal.>\n\nWha... What are you doing here?", completion = "You slew their conqueror? Then we haven't much time...\n\nThe Crimson Sigil is a group comprised of Illidan's elite minions. They are at the top of the chain of command for all Illidari forces outside of the Black Temple. These soldiers communicate directly with the Betrayer here, carrying out his orders without question.\n\nThey are the fiends that will undoubtedly lead an assault on this world, trampling under foot all that would stand in their way.", sourceObjectiveStatus = "unverified-source-field" }
quests[10794] = { id = 10794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rogues of the Shattered Hand", description = "{name}, there are secrets in the world that we do not yet possess.  The Shattered Hand in Orgrimmar can lead you to one of these secrets: the method for brewing deadly poisons.  Do as they ask and you will gain their trust.\n\nTo reach Orgrimmar, take the portal in Silvermoon City to Undercity.  Then, travel outside the city and find the nearby tower where the goblin Zepplins pick up their passengers.  From there, fly to the city of Orgrimmar where you can find Shenthul in the Cleft of Shadow.", sourceObjective = "Speak with Shenthul in Orgrimmar.", completion = "So, you want to work for the Shattered Hand?  Seems like we're getting someone new every day.\n\nPay close attention and I'll explain what you have to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[10795] = { id = 10795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Date with Dorgok", description = "Good, I've seen you around and I've been meaning to speak to you about a matter of some importance.\n\nThere are reports coming in that for some reason the Bloodmaul ogres are planning an offensive against Sylvanaar and Ruuan Weald.  We don't know who or what is pushing them to do this, but I intend to nip their plan in the bud!\n\nBloodmaul Camp is where the attacks are to be staged from.  Head northwest down the ramp out of the Ruuan Weald and you will find it.  I want you to kill their leader, Dorgok!", sourceObjective = "Slay Dorgok at Bloodmaul Camp.", completion = "With Dorgok dead, the Bloodmaul ogres are without leadership, and should be in disarray until another leader arises from within their ranks.\n\nThank you, {class}, I think we can breathe a little easier now.", sourceObjectiveStatus = "unverified-source-field" }
quests[10796] = { id = 10796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crush the Bloodmaul Camp!", description = "I've heard that you've done us more than proud in the fight against the ogres thus far.  Now, I would ask that you face them again.  I want you to crush the ogres at Bloodmaul Camp!\n\nTo get down there, head northwest down the ramp out of the Ruuan Weald.  You'll find them at the base of the ramp.\n\nGood luck, {class}!", sourceObjective = "Slay 10 Bloodmaul Maulers and 5 Bloodmaul Warlocks.", completion = "<The lieutenant nods her head in obvious approval of your killing prowess.>\n\nI am impressed, {name}.  Your reputation seems to be well-deserved.\n\nEvery time one of the ogres is felled, we come one step closer to ridding ourselves of a danger that has no intention of leaving us in peace.", sourceObjectiveStatus = "unverified-source-field" }
quests[10797] = { id = 10797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favor of the Gronn", description = "A token in the form of a small statuette falls from Dorgok's dead clutch.  It bears a striking resemblance to one of the gronn.\n\nSurely, Commander Haephus Stonewall at Evergrove in the Ruuan Weald, up the ramp to the east, would be interested in this!", sourceObjective = "Deliver Gorgrom's Favor to Commander Haephus Stonewall at Evergrove in the Blade's Edge Mountains.", progress = "Hello, lad, what news do you bring?", completion = "Oh, now that's pretty.  Looks a lot like those gronn that are always bossing the Bladespire ogres around.\n\nOdd that you should find it in the hands of one of the Bloodmaul leaders.", sourceObjectiveStatus = "unverified-source-field" }
quests[10798] = { id = 10798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pay the Baron a Visit", description = "This is bad news.  Gorgrom the Dragon-Eater is behind the recent Bloodmaul plans against Sylvanaar!\n\nWhy he's manipulating them, and not just using the Bladespire, I don't know.  But if we're to deal with a gronn, we're going to need help.\n\nI know a man who is wise in the ways of all sorts of exotic magics.  Baron Sablemane is his name, and you can find him at the Circle of Blood, back down the ramp to the northwest, and then southwest through the canyon.\n\nAsk him to fashion us a trap for the gronn.", sourceObjective = "Speak with Baron Sablemane at the Circle of Blood in the Blade's Edge Mountains.", completion = "Ah, an envoy from the vaunted Alliance.  Tell me, lackey, why is it that you are here, begging me for this thing, instead of your illustrious commander?\n\nCould it be that he is afraid of me?  It says something about you that you are not, but I haven't quite decided yet what that is.", sourceObjectiveStatus = "unverified-source-field" }
quests[10799] = { id = 10799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Churning Gulch", description = "Very well, I'll create this trap, but first I want something in return.\n\nThere happens to be a nearby gronn that is in possession of an item that I want, but you can't face him, not yet anyway.\n\nSo, you and I are going to fashion a sleeping powder from the poison of the nearby crust bursters.\n\nYou'll find them in the Churning Gulch to the southwest.  Bring me a number of their glands, and be quick about it!", sourceObjective = "Collect 7 Crust Burster Venom Glands.", progress = "You have all of the venom glands?  If not, begone and waste no more of my time until you do!", completion = "Very well.  A simple, if mundane, task has been completed.  Now, hand me the glands and I will perform the difficult part.", sourceObjectiveStatus = "unverified-source-field" }
quests[10800] = { id = 10800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goodnight, Gronn", description = "I've outdone myself again.  I've fashioned a sleeping powder for you to use on Grulloc, the gronn I spoke of who is guarding what I want.\n\nGrulloc keeps himself at the Cursed Hollow, an area at the eastern edge of Dragons' End on the other side of the Circle of Blood.\n\nIf I were you, I wouldn't tarry long once you have his sack.  The effects of the dust won't last long.", sourceObjective = "Collect Grulloc's Sack.", progress = "You are before me again, {class}.  This must mean that you've procured the sack out from underneath Grulloc's nose.", completion = "<Baron Sablemane peers inside the gronn's sack and seems satisfied.>\n\nVery well, you have upheld your end of the bargain.  And now, I will gift your Commander Stonewall with the trap.", sourceObjectiveStatus = "unverified-source-field" }
quests[10801] = { id = 10801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's a Trap!", description = "There's nothing more that I hate in this world than the sons of Gruul and their father!  They slaughtered my people, and my children, and now I will have a taste of revenge!\n\nI have fashioned a trap from some dragon fire, and if you're clever enough, you might just be able to use it to kill a gronn.\n\nI'm sure that you have a particular gronn in mind; it matters not to me which one you kill.  Just hurry, take the trap to your Commander Stonewall.\n\nMy thirst for revenge must be quenched!", sourceObjective = "Deliver the Dragonfire Trap to Commander Haephus Stonewall at Evergrove in the Blade's Edge Mountains.", progress = "Did the baron fashion us a trap?  One powerful enough to kill a gronn?", completion = "Hmm, a trap fashioned from the essence of dragon flame?  I wonder how Sablemane comes by such rarified substances?\n\nIt does not matter.  What does matter is that we are going to use it to slay a son of Gruul!", sourceObjectiveStatus = "unverified-source-field" }
quests[10802] = { id = 10802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorgrom the Dragon-Eater", description = "We must show the ogres that we are not to be trifled with. We must send a message.\n\nTravel to Boulder'mok and kill the ogres there. Make sure you keep their heads.\n\nThen go to Gorgrom's altar and place the trap there for him. Gorgrom will appear, and you must lure him into the trap. When he is dead, mount your grisly totems near his corpse, so that the ogres may look at their fallen master and their fallen brothers, and know the price for seeking to destroy us.", sourceObjective = "Collect 3 Grisly Totems from Boulder'mok ogres. Then, use Sablemane's Trap at Gorgrom's Altar to summon and kill Gorgrom the Dragon-Eater.\n\nWhen Gorgrom is dead, place the 3 Grisly Totems near his corpse.", progress = "Has the message been delivered?", completion = "Well done, {name}. Well done!\n\nI suspect we will hear little more from the ogres and their master.", sourceObjectiveStatus = "unverified-source-field" }
quests[10803] = { id = 10803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slaughter at Boulder'mok", description = "I know that we have plans for you to head to Boulder'mok. I have something that I want you to do while you are there.\n\nWe must take any chance we can get to strike down the ogres of these mountains, or they will overrun us, and all that we have bled and died for will be for nothing!\n\nBoulder'mok lies to the west. Travel southwest, cross the bridge and head through the tunnel. On the west side of the Raven's Wood you will find them.\n\n{name}, I want you to wipe out the Bladespire ogres of Boulder'mok.", sourceObjective = "Slaughter 5 Boulder'mok Brutes and 3 Boulder'mok Shaman.", completion = "<Lieutenant Fairweather grins at the story that you tell her about your adventures at Boulder'mok.>\n\nAh, I wish that I could have been there with you.  Let me tell you something, {name}: never accept any duty that keeps you from the glory of the battlefield!\n\nHah!  After all of the ogre killing that you've done, are there any still left in these mountains for me?!", sourceObjectiveStatus = "unverified-source-field" }
quests[10804] = { id = 10804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kindness", description = "Something has them spooked, {race}.\n\n<Mordenai points to the nether drakes flying overhead.>\n\nThey won't even come down to feed. I have seen several fall to the earth, dead from exhaustion before their bodies hit the ground.\n\nWe must save them! The Rocknail flayers that are found near the crystals are their natural prey. Kill flayers and take their carcasses. Place a carcass in the field and stand extremely still. As long as you do not make any aggressive motions, they will not attack you.", sourceObjective = "Mordenai at Netherwing Fields in Shadowmoon Valley wants you to feed 8 Mature Netherwing Drakes.", progress = "I cannot save them by myself, {name}!", completion = "You are a kind and compassionate {race}, friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[10805] = { id = 10805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Massacre at Gruul's Lair", description = "You've proven yourself resourceful, and now I think I'm going to put you to personal use in my own fight against Gruul and his sons.\n\nThe Bladespire clan are the favored of the gronn, and while you may have thinned out their numbers elsewhere, you haven't yet dealt with their strongest.\n\nGruul protects the exterior of his lair with only the toughest of ogres, and it is those that you must kill.  Head north through the Daggermaw Canyon and you will find Gruul's Lair at the end.", sourceObjective = "Slay 10 Bladespire Enforcers, 5 Bladespire Battlemages, 5 Bladespire Ravagers and their leader, Fingrom.", completion = "Very well, I chose wisely when I selected you to spearhead my fight.  Time to ramp things up to a whole new level, I think.\n\nYou remember that little goodie that you stole for me out from underneath Grulloc's nose?  You're going to get a chance to put it to good use.", sourceObjectiveStatus = "unverified-source-field" }
quests[10806] = { id = 10806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Showdown", description = "The time has come for us to face Goc, the master of the Bladespire ogres. It is also time that I take a hand in events, to see the last of the gronn's life.\n\nTake my signet ring. When you come to the Altar of Goc, use it, and I will come to join you.\n\nTogether we will destroy Goc.", sourceObjective = "Use Sablemane's Signet at the Altar of Goc, then kill Goc.", progress = "In time, all the sons of Gruul will be destroyed.", completion = "You fought surprisingly well for a {race}, and it was an honor to have you at my side.  My transformation must have been quite a surprise for you.  I trust it was not too startling?\n\nLet us keep my true identity between the two of us for now, shall we?  In return, and for your adept service, I grant you your choice of any of these baubles.", sourceObjectiveStatus = "unverified-source-field" }
quests[10807] = { id = 10807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ashtongue Broken", description = "The Ashtongue tribe is feared among all Broken.  It consists of the most vicious and bloodthirsty individuals, handpicked by Akama himself.  They are as fierce and ruthless as any naga, demon or blood elf in Illidan's army and they have been deployed in large numbers at the Ruins of Baa'ri, to the north.  Go there and put a dent in their numbers before they get a chance to mount an attack on us.", sourceObjective = "Varen the Reclaimer wants you to go to the Ruins of Baa'ri and slay 3 Ashtongue Handlers, 4 Ashtongue Warriors and 6 Ashtongue Shaman.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", completion = "Glory to the Scryers, {name}.  You've done the Seer's bidding by defeating those who follow Illidan.", sourceObjectiveStatus = "unverified-source-field" }
quests[10808] = { id = 10808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thwart the Dark Conclave", description = "The spirits of the dark conclave seek to summon an ancient and powerful evil through a ritual conducted at the lava pits to the south of the Sketh'lon Base Camp.\n\nGul'dan's magic mingled with their own, empowering them to aid this creature in manifesting in our world! We must not allow this to happen, {name}. The death and destruction it would bring are unimaginable!\n\nCarry the staff with you to the site of the summoning and use its magics to stop the dark conclave once and for all!", sourceObjective = "Slay the Dark Conclave Ritualists and use the Staff of Parshah to end the Dark Conclave's summoning ritual, then return to Parshah in the Magma Fields.", progress = "Is it done, {name}? Have you stopped the dark conclave from completing their ritual?", completion = "I have sought a way to stop the dark conclave for years, and you have succeeded where I failed. The conclave's dark rituals will threaten us no more.\n\nI often feel guilty for abandoning my fellows all those years ago, but now I finally know that I made the right decision. If not for my wavering conscience then, I might have ended up as a shade among them.", sourceObjectiveStatus = "unverified-source-field" }
quests[10809] = { id = 10809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Worg Master Kruush", description = "The poster reads:\n\n\"Worg Master Kruush leads the worg riders of the Bleeding Hollow clan.  A price has been placed on his head, for his riders exact heavy tolls on supply trains to Spinebreaker Post.\"\n\n\"Scouts report him within Zeth'Gor, and the hero able to bring the severed head of this villain to me will earn the thanks of the Horde, and a large bounty.\"\n\n\"-Captain Darkhowl\"", sourceObjective = "Kill Worg Master Kruush and bring his head to Captain Darkhowl in Spinebreaker Post.", progress = "Report, {name}.  Is that Bleeding Hollow blood I see on your sleeve?  I hope so!", completion = "Ah, so you slew that villain, Kruush!  Well done, {name}!  Well done!  His death will defang those cursed worg riders.  In fact, I hope you took a few of them out during your foray into Zeth'Gor!\n\nHere's your reward.  You earned every piece of it!", sourceObjectiveStatus = "unverified-source-field" }
quests[10810] = { id = 10810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Damaged Mask", description = "As you examine the damaged mask, you hear strange sounds coming from within. If the mask wasn't damaged you might be able to hear the sounds more clearly.\n\nO'Mally Zapnabber in Ruuan Weald might be able to fix the mask.", sourceObjective = "Deliver the Damaged Mask to O'Mally Zapnabber at Evergrove in the Blade's Edge Mountains.", progress = "Don't be bothering me! Can't you see I'm trying to unlock mysterious powers?", completion = "Ah, what's that you have? Let me take a closer look, {class}. Yes, yes... it's just what I thought it was. Here, let me fix this mask for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[10811] = { id = 10811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek Out Neltharaku", description = "Their patron soars high above, {name}. Perhaps the kindness that you showed his children has moved his heart. Seek Neltharaku out and enlist his aid. Together, you may be able to solve the plight of the Netherwing drakes.\n\n<Mordenai points to the sky.>\n\nFly high, friend...", sourceObjective = "Seek out Neltharaku, patron of the Netherwing Dragonflight.", completion = "My children have told me of your heroic deeds, {race}. There is more that you can do.", sourceObjectiveStatus = "unverified-source-field" }
quests[10812] = { id = 10812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mystery Mask", description = "Ok, it should work now. What is it, you ask? Why, it's a communication device - it allows those blockheads to communicate with each other. You know, the Burning Legion! I would suggest that you hand this mask to Wildlord Antelarion. He's over there pacing around. Always moving, he is.\n\nWell get moving, he's been trying to get his hands on one of these for sometime now.", sourceObjective = "Deliver the Mystery Mask to Wildlord Antelarion at Evergrove in the Blade's Edge Mountains.", progress = "I cannot believe my eyes.", completion = "That mask you hold in your hands is a Felsworn gas mask and by the appearance, it's not damaged. The trouble we can cause Forge Camp: Anger is boundless. Are you interested in helping us out, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[10813] = { id = 10813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eyes of Grillok", description = "{name}, you have braved the lair of the Bleeding Hollow orcs, dreaded Zeth'Gor, and survived!  Perhaps you have the strength to aid me, for I aim to gaze into the mind of its darkest witch, Grillok!\n\nTake this shard.  Use it to ensorcel an Eye of Grillok and bind it to yourself.  Return here and approach my cauldron... and it will pull the eye from you.\n\nGo, {name}.  And use care -- An Eye of Grillok will betray you to our enemies if given the slightest opening!", sourceObjective = "Use Zezzak's Shard to capture an Eye of Grillok, then approach Zezzak's cauldron to extract it. After it is removed, return Zezzak's Shard to him.", progress = "The orcs of the Bleeding Hollow Clan were dark allies long ago... and even darker enemies now.", completion = "I am indebted to you, {name}.  You have again braved Zeth'Gor and held its darkness close to your heart.  I will study the eye and perhaps pierce the secrets of its master, Grillok.\n\nLet us hope that he can no longer use its magic!", sourceObjectiveStatus = "unverified-source-field" }
quests[10814] = { id = 10814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharaku's Tale", description = "I have information that you may find useful. Please listen to what I have to tell you, {race}.", sourceObjective = "Speak with Neltharaku and listen to his story.", progress = "Allow me to finish telling you my tale.", completion = "So you will help us?", sourceObjectiveStatus = "unverified-source-field" }
quests[10815] = { id = 10815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Journal of Val'zareq: Portends of War", description = "This journal documents the recent activities of Illidan's armies. It also explains why Val'zareq was parading around the Path of Conquest. He was personally responsible for the capture of a high general of the Sha'tar.\n\nThis general is being held at a post known as Crimson Watch, located at the southern end of the Path of Conquest. A mysterious faction, calling itself the Crimson Sigil, is charged with his incarceration. If you choose to investigate, it would be wise to bring allies.", sourceObjective = "Locate Marcus Auralion, High General of the Sha'tar, at Crimson Watch.", sourceObjectiveStatus = "unverified-source-field" }
quests[10816] = { id = 10816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming Holy Grounds", description = "You did well against the Broken in Baa'ri, {name}.  Let's see how well you do against Illidan's most feared army.\n\nThe fel orcs of the Shadowmoon Clan occupy the Ata'mal Terrace, once a very holy site where ata'mal crystals were used in spiritual ceremonies.\n\nWe had reason to believe they were hiding an actual ata'mal crystal in the vicinity, but our scrying has revealed nothing.  Nevertheless, the fel orcs are on draenei holy ground and their presence must be dealt with.", sourceObjective = "Vindicator Aluumen wants you to slay 8 Shadowmoon Slayers, 8 Shadowmoon Chosen and 4 Shadowmoon Darkweavers.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", completion = "Excellent work, {class}.  May the Light continue to protect you.", sourceObjectiveStatus = "unverified-source-field" }
quests[10817] = { id = 10817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Retribution", description = "You did well against the Ashtongue Broken, {name}.  I have another challenge for you, should you be up to it.\n\nNot too long ago, the Sanctum of the Stars suffered a tremendous attack by Illidan's fel orcs.\n\nWe've determined it was perpetrated by the Shadowmoon orcs who occupy the Ata'mal Terrace.\n\nShow them that the Scryers are not to be trifled with.", sourceObjective = "Varen the Reclaimer wants you to slay 8 Shadowmoon Slayers, 8 Shadowmoon Chosen and 4 Shadowmoon Darkweavers.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", completion = "You've gained my utmost respect today, {name}.\n\nSlaying one fel orc is not an easy task.  Massacring a score of them is, well... heroic.", sourceObjectiveStatus = "unverified-source-field" }
quests[10818] = { id = 10818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron Sablemane Has Requested Your Presence", description = "{name}, while you were out being one hell of a {class}, Baron Sablemane sent his pet dragon up here with a message.\n\nHe's asked for you personally.  From what I understand, he wants you to head up his own fight against the gronn.\n\nI guess you're the most qualified person in all of Outland to help him, but if I were you, I'd get in contact with a couple of friends first and ask them to join you at the Circle of Blood.", sourceObjective = "Speak with Baron Sablemane at the Circle of Blood in the Blade's Edge Mountains.", completion = "Ah, I see that you decided to take your sweet time answering my summons.\n\nNo matter, I have plenty of time to exact my revenge, and I intend for you to be my proxy in the coming battle!", sourceObjectiveStatus = "unverified-source-field" }
quests[10819] = { id = 10819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felsworn Gas Mask", description = "I have a very special mission for you, {name}. I need you to infiltrate Forge Camp: Anger east of here. When you enter the camp you will need to wear the Felsworn gas mask and locate the Legion communicator. Once you have located the communication device speak with whomever is on the other side of the device.\n\nIf all works out you can trick the demon into something devious! Try telling the demon that Camp Anger has revolted.\n\nGood luck to you {class}.", sourceObjective = "Wear the Felsworn Gas Mask and use the Legion Communicator at Forge Camp: Anger in the Blade's Edge Mountains.\n\nProvided item:", completion = "What's the meaning of this! No one summons me! Speak, or I will silence you forever!", sourceObjectiveStatus = "unverified-source-field" }
quests[10820] = { id = 10820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deceive thy Enemy", description = "For every moment I hear silence, you draw closer to your death! SPEAK!\n\nWhat? The camp has revolted? This cannot possibly be true! My minions would not dare undermine my authority.\n\nWell then, every last one of them will pay for this treachery, they will pay dearly. Silence them all and be done with it! Report back to me once you have carried out my order or you shall be dealt with.", sourceObjective = "Slay 4 Doomforge Attendants and 4 Doomforge Engineers.", progress = "My patience is tiring, why have you not finished them?", completion = "That will surely teach those that don't do as I say...\n\nBy the way... where is Doomcryer? Why have you reported this revolt to me and not she?", sourceObjectiveStatus = "unverified-source-field" }
quests[10821] = { id = 10821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You're Fired!", description = "Doomcryer did nothing to stop the revolt? How dare she! She has been trying to undermine my authority for some time. However, this time will be her last. You must summon her and deal with her personally.\n\nHer anger guards hold the keys that summon her to Forge Camp: Anger. Retrieve the five keys and activate the five Legion obelisks. The obelisks have a short duration, so make sure they are all activated at the same time. Remember, the anger guards carry more keys.", sourceObjective = "Slay Doomcryer.", progress = "Are you looking to join my list of those expendable? Get those keys and silence Doomcryer!", completion = "That is great news, great news indeed, {name}. I could not have asked for a better outcome. Your service to our people is most greatly appreciated; choose one of the following heroic items.\n\nYour name will forever be remembered in our peoples' hearts.", sourceObjectiveStatus = "unverified-source-field" }
quests[10822] = { id = 10822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Single Sunfury Signet", progress = "Even the smallest contribution to our cause is noted, {name}.  Our enemies are many, but we shall prevail!", completion = "Victory to the Scryers!  Kael's forces will soon crumble." }
quests[10823] = { id = 10823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Sunfury Signets", progress = "How fares the battle against Kael's forces?", completion = "You're making a name for yourself, {name}.  Keep it up." }
quests[10824] = { id = 10824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunfury Signets", description = "The survival of the Scryers hinges on outrecruiting Kael'thas.  Every pilgrim from Quel'Thalas that joins his side brings him closer to victory.  The opposite is true for us.\n\nSoon, however, we will run out of recruits and it will come down to what side can kill the other quicker.  Prove your worth to the Scryers by bringing me Sunfury signets worn by  high-ranking blood elves allied with Kael'thas and Illidan.  You'll find them at Eclipse Point to the west and the Ruins of Karabor, to the northeast.", sourceObjective = "Battlemage Vyara at the Sanctum of the Stars wants you to bring her 10 Sunfury Signets.\n\nPerforming quests for the Scryers will cause you Aldor reputation level to decrease.", progress = "Go on, {name}.  Speak.", completion = "Kael's elves are extremely well-trained.  Excellent job.", sourceObjectiveStatus = "unverified-source-field" }
quests[10825] = { id = 10825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Truth Unorbed", description = "This strange, magical orb drops from beneath the contour feathers of the arakkoa.\n\nSuffused with an eerie, purple glow, the orb pulses to an unheard beat.  Holding it makes you mildly uncomfortable, and so you quickly place it within your pack.\n\nPerhaps Tree Warden Chawn at Ruuan Weald to the west, through the tunnel and across the Wyrmskull Bridge, would be interested in examining it?", sourceObjective = "Deliver the Orb of the Grishna to Tree Warden Chawn at Evergrove in the Blade's Edge Mountains.", progress = "{class}, do you feel that?  I sense something unnatural and evil nearby.", completion = "Yes, it's that orb you have there!  Odd, it appears to be of arakkoan design.  Were you recently at Grishnath?\n\nAll right, that explains that, but I wonder what diabolical purpose this object serves.  Though it radiates evil, it also somehow feels as if it were connected to the natural world.\n\nHere, allow me to try activate it.  The evil is so strong within it, there's some sort of residual memory here....", sourceObjectiveStatus = "unverified-source-field" }
quests[10826] = { id = 10826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marks of Sargeras", description = "By now it should be clear to you why we oppose the Burning Legion and those who serve them.\n\nIf you wish to prove yourself to the Aldor, bring me the insignias of high-ranking Legion and their Shadow Council followers.  Here in Shadowmoon you will find a strong Legion presence to the far west in Legion Hold and the Deathforge.", sourceObjective = "Bring 10 Marks of Sargeras to Harbinger Saronen in Shadowmoon Valley.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", progress = "Do you bear any of our enemies' insignias, {name}?", completion = "Your courage is strong, friend.  Let it be known to all that you are a true ally of the priesthood!", sourceObjectiveStatus = "unverified-source-field" }
quests[10827] = { id = 10827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Marks of Sargeras", progress = "Do you bear more of our enemies' insignias, {class}?  We will fight the Legion until the Light prevails.", completion = "Destroy the enemies of the Light wherever you find them, {name}." }
quests[10828] = { id = 10828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Single Mark of Sargeras", progress = "I'll take any leftover marks you might have.  Do not worry; your actions will be duly noted.", completion = "You continue to prove your worth, {name}." }
quests[10829] = { id = 10829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treebole Must Know", description = "This is troubling!  The arakkoa are causing the ancients and protectors to become possessed by evil spirits!\n\nBut, there is one ancient that could not possibly have been affected.  His name is Treebole, and you must go to him at once if we're to save the trees of the Raven's Wood!\n\nGo back to the Raven's Wood.  You will find him at the fork in the path just past Grishnath.", sourceObjective = "Speak with Treebole, an ancient of lore who lives in the Raven's Wood of the Blade's Edge Mountains.", completion = "Greetings, tiny {race}.  The birds in my boughs whispered to me that you were to be expected.\n\nYou are here to help free the trees of the woods from their possession?", sourceObjectiveStatus = "unverified-source-field" }
quests[10830] = { id = 10830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exorcising the Trees", description = "The Grishna have caused the leafbeards and stonebarks to be inhabited by evil koi-koi spirits.\n\nWe must save the trees or soon all of the Raven's Wood will be lost forever!\n\nCombine the magic of a Grishnath orb, found throughout Grishnath, with a dire pinfeather from a dire raven.\n\nUse the resultant exorcism feather to draw out and slay the koi-koi spirit as quickly as possible.  The stonebarks are too powerful for this ritual, but if enough leafbeards are saved, they will be freed as well.", sourceObjective = "Collect 5 Grishnath Orbs and 5 Dire Pinfeathers and then combine them into Exorcism Feathers. Use these feathers to exorcise and slay 5 Koi-Koi Spirits from the Raven's Wood Leafbeards.", progress = "The evil that is inhabiting the trees is beginning to seep into every natural thing in the woods.\n\nYou must act quickly, {name}, before all is lost!", completion = "The evil is lifting from the Raven's Wood!  Can you feel it, {name}?\n\nYou have saved us, and all of the surrounding wildlife, from certain destruction, little one!\n\nI keep stashed four magic rings amongst my boughs for such occasions as this, when a hero arises to do some great deed.\n\nYou are one such hero!  On behalf of all of the Raven's Wood, we give you thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[10831] = { id = 10831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Becoming a Mooncloth Tailor", description = "I can teach you the ways of mooncloth tailoring, if you are interested.. By specializing in mooncloth tailoring, creating primal mooncloth will yield twice the normal amount and you will have access to several exclusive patterns. All that is required is that you pass a simple test.\n\nAs to the test, your task is to create a small sample of primal mooncloth in the moonwell at Cenarion Refuge. I will provide all the materials you'll need. When you've created the sample, bring it back to me for examination.", sourceObjective = "Use the Square of Imbued Netherweave while standing in Cenarion Refuge's moonwell to create a Sample of Primal Mooncloth. Bring the completed sample back to Nasmara Moonsong in Shattrath's Lower City.\n\n*WARNING!* You can only select one tailoring specialization.", progress = "Have you created the primal mooncloth sample?", completion = "<Nasmara examines the cloth, turning it over in her hands.>\n\nThis is an exceedingly fine sample, {name}. You will make an excellent mooncloth tailor.", sourceObjectiveStatus = "unverified-source-field" }
quests[10832] = { id = 10832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Becoming a Spellfire Tailor", description = "I can teach you the ways of spellfire tailoring if you wish, but be warned, it's a dangerous pursuit.\n\nCreating spellcloth in Netherstorm attracts powerful nether-wraiths. I'm searching for a way to lessen backlash, but I need more nether-wraith essence for my research.\n\nTake this beacon with you to Netherstorm and use it to summon a nether-wraith. Bring back its essence and I'll agree to teach you. As a spellfire tailor, you'll receive twice as much cloth and have access to exclusive patterns.", sourceObjective = "Bring a sample of Nether-wraith Essence to Gidge Spellweaver in Shattrath's Lower City.\n\n*WARNING!* You can only select one tailoring specialization.", progress = "Did you get the nether-wraith sample?", completion = "<Gidge examines the nether-wraith essence.>\n\nEven this small a sample of the creature's essence radiates power. Perhaps I misunderstood what's happening. We're not angering the wraiths by taking energy from the environment. Rather, the wraiths and the environment are the same thing!\n\nDon't hesitate to let me know if you make any further discoveries, now that you've become a spellfire tailor.", sourceObjectiveStatus = "unverified-source-field" }
quests[10833] = { id = 10833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Becoming a Shadoweave Tailor", description = "If you become a shadoweave specialist, you will make twice as much shadowcloth as an average tailor and have access to several exclusive patterns.\n\nOf course, any tailor can use the Altar of Shadows, but a shadoweave tailor possesses a deeper attunement to the altar, unlocking powers that few can fathom.\n\nTake this crystal to eastern Shadowmoon Valley, and find Netherwing Pass leading south from the Netherwing Fields. Near the world's edge, you will find the Altar of Shadows. Use the crystal there.", sourceObjective = "Use the Crystal of Deep Shadows near the Altar of Shadows to deepen your attunement to the altar, then return to Andrion Darkspinner in Shattrath's Lower City.\n\n*WARNING!* You can only select one tailoring specialization.", progress = "Have you used the crystal's power to deepen your attunement to the Altar of Shadows?", completion = "I can see that your visit to the altar was a success. There is a subtle difference about you that few will see, but there's no doubt it's there.", sourceObjectiveStatus = "unverified-source-field" }
quests[10834] = { id = 10834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grillok \"Darkeye\"", description = "Grillok Darkeye has wagered a piece of himself to dark powers, and gained great magic for it.  His lost eye burns deep in some hellish pit, now a demon's trinket... and the patch that covers his betrayal holds its own dark secrets.\n\nBring me Grillok's eyepatch, {name}, and I will reward you greatly for your service...", sourceObjective = "Kill Grillok Darkeye and bring Grillok's Eyepatch to Zezzak in Spinebreaker Post.", progress = "The evils of the Bleeding Hollow orcs know no bounds, and are rivaled by only their Shattered Hand cousins.", completion = "Ah, yes.  Just as some who lost a hand or a leg in battle will oftentimes feel their severed limb, I wonder if Grillok still clutched at his lost eye in his dark, dark dreams...\n\nI too will dream on this, and if fortune is with us then perhaps I will learn what drew Grillok and the Bleeding Hollow orcs to succumb to demons.", sourceObjectiveStatus = "unverified-source-field" }
quests[10835] = { id = 10835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apothecary Antonivich", description = "{name}, I have prepared a preliminary report of my findings regarding the Bleeding Hollow orcs.  My colleague in Thrallmar, Apothecary Antonivich, will be happy to receive them.  He too studies the phenomenon of fel orcs... in hopes of preventing such a tragedy from again befalling our orcish allies.\n\nTake him this report, and I will continue my study of the blood you brought me.  If fortune is with us, we will isolate the cause of the fel orc affliction.", sourceObjective = "Bring Albreck's Findings to Apothecary Antonivich at Thrallmar in Hellfire Peninsula.", progress = "Good day, {name}.  And how is your stay in Hellfire Peninsula?  I trust it has been fruitful...", completion = "Ah, a report from Albreck?  Very good.  The Royal Apothecary Society works feverishly to determine how the orcs of Hellfire Peninsula became fel orcs.  Their betrayal is unforgivable... and we must ensure that our orc friends are forever safe from future corruption.", sourceObjectiveStatus = "unverified-source-field" }
quests[10836] = { id = 10836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltrating Dragonmaw Fortress", description = "I require time so that I may devise a plan to save my children and mate. You will buy me this time, mortal.\n\nVenture into Dragonmaw Fortress, located on the eastern edge of the Netherwing Fields, and lay waste to all Dragonmaw orcs that you find. The ensuing chaos and confusion should have a considerable impact on their plans.\n\nBe warned, some of my kin are too far gone - their minds corrupted by the Dragonmaw. For them, the only resolution is death. You have my permission to end their lives as well.", sourceObjective = "Neltharaku, flying high above Netherwing Fields in Shadowmoon Valley, wants you to slay 15 Dragonmaw Orcs.\n\nAny Dragonmaw Orc in Dragonmaw Fortress will suffice.", progress = "Is it done? I can only hope that it is not too late...", completion = "Well done, {name}. I have discovered a way in which we can free the enslaved drakes that are being held at Dragonmaw Fortress.", sourceObjectiveStatus = "unverified-source-field" }
quests[10837] = { id = 10837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Netherwing Ledge!", description = "I believe that I can imbue nethervine crystals with my own essence. The power contained within these imbued crystals should be sufficient to free enslaved drakes of their masters' grasps.\n\nTravel to Netherwing Ledge, an island located off the broken shelf of Shadowmoon Valley, to the southeast. It is on Netherwing Ledge that you will find nethervine crystals. Return to me when you have collected enough crystals to fill your packs.\n\nAnd {name}, Beware the Dragonmaw that now inhabit the island.", sourceObjective = "Neltharaku, flying high above Netherwing Fields in Shadowmoon Valley, wants you to collect 12 Nethervine Crystals from Netherwing Ledge.", progress = "I require nethervine crystals.", completion = "<Neltharaku takes the crystals from you.>\n\nI will prepare the crystals for you now.", sourceObjectiveStatus = "unverified-source-field" }
quests[10838] = { id = 10838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Demoniac Scryer", description = "The Demoniac Scryer is now ready.  Take it behind Hellfire Citadel, to Hellfire Basin, and summon it upon the ground.  It will then begin to attune itself to Hellfire Citadel.  After its attunement, speak to the Scryer and transcribe what it tells you.  Bring that transcription to me...\n\nGo, {name}, but only when you are ready.  There is no doubt that Hellfire Citadel will detect the Scryer and send wardens to destroy it!", sourceObjective = "Use the Demoniac Scryer in Hellfire Basin, wait for it to attune, and then take a reading.\n\nReturn the Demoniac Scryer and the Demoniac Scryer Reading to Apothecary Antonivich in Thrallmar.", progress = "Do you have the reading?  Has your mission with the Demoniac Scryer been successful?", completion = "You obtained the reading?  Excellent -- I am sure this data will prove invaluable to our research.  I will disseminate it to Apothecaries Zelana and Albreck.\n\nYou should be proud, {name}.  Your strength and bravery is unquestionable... as is your service to the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[10839] = { id = 10839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veil Skith: Darkstone of Terokk", description = "Veil Skith lies to the northwest of the caravan and to the south of Shattrath in a secluded grove of the forest. It is rumored that the colony of Skettis has constructed a maligned altar of worship. This Darkstone of Terokk must be purified if the arakkoa of Skith are ever to be redeemed.\n\nTake this Rod of Purification and cast it upon the Darkstone. Blessed by A'dal, the rod's purity might be enough to bring clarity to the Darkstone. Go now and may the light shine upon thee.", sourceObjective = "Use the Rod of Purification on the Darkstone of Terokk in Veil Skith and return to Kirrik the Awakened at the Refugee Caravan in the Bone Wastes.", progress = "Darkness surrounds us. What have you to say about Veil Skith?", completion = "I heard the explosion from here. Not with my ears, but with my heart.\n\nIf the touch of the blessed Naaru, A'dal, is not enough to bring the arakkoa to redemption, nothing will be. Those who have not given themselves over to the Light are mere servants of evil.\n\nThey must be destroyed.", sourceObjectiveStatus = "unverified-source-field" }
quests[10840] = { id = 10840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tomb of Lights", description = "To the east, buried under the charred sand, is the Tomb of Lights, a lost resting place of the dead.  Before our caravan was ambushed I was going to journey to the tomb and cleanse it of evil spirits.  \n\nLittle did I know it was already infested with another kind of evil.  Even now the ethereals plunder the bodies of the fallen for trinkets and keepsakes that were given to the dead centuries ago.  \n\nThere is little I can do while our caravan struggles to survive.", sourceObjective = "High Priest Orglum wants you to journey to the Tomb of Lights and kill 10 Ethereal Nethermancers and 10 Ethereal Plunderers and then return to him at the Refugee Caravan.", progress = "How many ethereals have you destroyed?  I hope it will be enough to drive them from the Tomb of Lights.", completion = "Out here in the wilds of Outland we are weak with few heroes to defend our rights, but you have given them something to fear {class}.  I do not think the ethereals will soon forget the strong right arm of {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10841] = { id = 10841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vengeful Harbinger" }
quests[10842] = { id = 10842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeful Souls", description = "The Tomb of Lights has become corrupted by the Shadow Council and the draenei dead have become cursed spirits, angry and confused with a burning hatred for the living.\n\nEnter the tomb and seek out these tragic victims. Give them the rest that they deserve.", sourceObjective = "High Priest Orglum wants you to journey into the Tomb of Lights and defeat 5 Vengeful Draenei.", progress = "You have saved us all.  What can we do to thank you?", completion = "You cannot know what you have done here {name}.  You have saved so many of us from an eternity of darkness.  There is little that I can do for the living and nothing that I could give that would thank you enough.  Take what seems useful to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[10843] = { id = 10843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Since Time Forgotten...", description = "Since time forgotten we have fought with the Bladespire ogres.\n\nWe have managed to push them back so that now they only hold a tenuous grip at Bladespire Outpost.  It's back the way that you came, on the southwestern edge of the Razor Ridge.\n\nProve your worth to me by killing their leader, Gnosh Brognat.\n\nLet us see what stuff you are made of when fighting the ogres.", sourceObjective = "Slay Gnosh Brognat, leader of the ogres at the Bladespire Outpost.", completion = "<Leoroxx appraises you with a keen eye, seemingly trying to take your measure.>\n\nThe death of Gnosh Brognat is a boon to all of the Mok'Nathal.  This is a good thing for you.\n\nLet us see if we can push the boundaries of your prowess just a bit more.", sourceObjectiveStatus = "unverified-source-field" }
quests[10844] = { id = 10844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forge Camp: Anger" }
quests[10845] = { id = 10845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slay the Brood Mother", description = "My hunters have just returned from a scouting mission to the Singing Ridge.  It seems that the nether drakes, which infest the crystals there, have increased greatly in number, and threaten to spill out into our laps.\n\nSince you have proven yourself a competent slayer, let us see if your {class} skills are the match of an adult drake.\n\nFind the Singing Ridge by heading south through the Scalewing Shelf.  Enter and slay their brood mother, Dreadwing.", sourceObjective = "Slay Dreadwing.", progress = "Though you will not further yourself in my eyes, there is no shame in admitting that you aren't up to the challenge of slaying the mother of the Singing Ridge nether drakes.\n\nIs that what you are here to tell me?", completion = "No?  You slew Dreadwing?  Perhaps I was wrong about you, {class}.\n\nPerhaps.\n\nStill, you have slain the chiefs of the three greatest threats that we face.  That is something to be proud of.\n\nI offer you a token of my appreciation, but don't let it go to your head.  You still do not fully understand what it is to be Mok'Nathal, and we may still have need to call upon your skills.", sourceObjectiveStatus = "unverified-source-field" }
quests[10846] = { id = 10846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Understanding the Mok'Nathal", description = "<Leoroxx looks you in the eye with the kind of stare that chills your soul.>\n\nYou come to the Mok'Nathal, but you do not understand us.  You do not understand our struggle to survive.\n\nIf you would understand us, then you will have to endure a taste of that struggle.\n\nTo the south are the Vekh'nir arakkoa.  They have enslaved a group of ogres in the caverns known as Trogma's Claim and their leader, Vekh is in there.\n\nSlay him!", sourceObjective = "Slay Vekh, leader of the Vekh'nir arakkoa.", progress = "We have many enemies.  Some we have chosen, and some, such as the Vehk'nir, we have not.\n\nRegardless, we shall slay all of their chieftains until none stand before us.", completion = "The Vekh'nir are the least of our adversaries.\n\nSo, you know how to slay an overgrown bird.  This does not make you a true warrior.  This does not give you a full understanding of our ways.\n\nBut it's a start.", sourceObjectiveStatus = "unverified-source-field" }
quests[10847] = { id = 10847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eyes of Skettis", description = "Doom harkens from the cliffs of Skettis.\n\nMy people, the arakkoa, face a fate shrouded in unspeakable evil. Too often have we abused dark magic for wrongdoing. Through A'dal I have learned of the Light and of redemption.\n\nTerokk watches his colonies from Skettis through orbs enchanted by the black art. Steal these Eyes from Veil Reskk and Veil Shienor in northern Terokkar. Let me see what Terokk sees. Let me look through the eyes of Skettis.", sourceObjective = "Bring the Eye of Reskk and the Eye of Shienor to Rilak the Redeemed in the Lower City section of Shattrath City.", progress = "You have returned, {class}. What news do you bring?", completion = "Your bravery should be commended. The guardians of Skettis do not part with their belongings willingly.\n\nBut heroics of the past are of little consequence now. We shall see if such bravery continues to persist in the future, for Terokk's gaze fixates on the south.\n\nThese Eyes are all seeing.", sourceObjectiveStatus = "unverified-source-field" }
quests[10848] = { id = 10848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veil Rhaze: Unliving Evil", description = "Veil Rhaze was a particularly wicked colony of Skettis.\n\nDespite the village's eradication by the Auchindoun disaster, Terokk's influence remained in the maligned spirits there. Travel west to Veil Rhaze and slay those murderous wretches. You'll find them to the west of the Shadow Tomb, on the border of Bone Wastes and Terokkar Forest.\n\nThis will be our first blow against Terokk and the guardians of Skettis.", sourceObjective = "Kill 4 Deathtalon Spirits, 4 Screeching Spirits and 2 Spirit Ravens and return to Kirrik the Awakened at the Refugee Caravan.", progress = "Evil grows in Veil Rhaze. Put it down, {race}.", completion = "Those foul spirits deserved to die. The death they would have wrought on others is reason enough.\n\nWe cannot hope to redeem those in Terokk's grasp. But we shall deliver them a devastating blow in the name of the Light.", sourceObjectiveStatus = "unverified-source-field" }
quests[10849] = { id = 10849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek Out Kirrik", description = "Other arakkoa took part in the betrayal of Terokk.\n\nKirrik recognized Terokk as a charlatan, not a prophet. The only prophecy Terokk envisioned was the doom borne of his own bidding.\n\nIt was Kirrik who led us bravely from Skettis. After our pilgrimage to Shattrath, Kirrik traveled to the colonies in search of others.\n\nThis missive tells of what the Eyes have seen. Kirrik must be told! Follow the road south out of Shattrath to the Bone Wastes and look for the caravan.", sourceObjective = "Take Rilak's Missive to Kirrik the Awakened at the Refugee Caravan in the Bone Wastes.", progress = "You have traveled far and bear news for me.", completion = "Rilak's tale is grim, traveler. As you can see from the state of the caravan, there is much sorrow and darkness in the forest of Terokk these days.", sourceObjectiveStatus = "unverified-source-field" }
quests[10850] = { id = 10850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nether Gas In a Fel Fire Engine", progress = "You uncover an opening through which fuel is loaded into the fel reaver.", completion = "The fel reaver's engine begins to rumble and sputter as you supply it with the incorrect fuel." }
quests[10851] = { id = 10851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Totems of My Enemy", sourceObjective = "Collect 5 Bladespire Totems.", progress = "Have you gone to Bladespire Outpost and taken their totems from them?", completion = "This looks like a good assortment.  We should be able to find a respectful use for one or two of them.\n\nIn fact, I have an idea for how to do just that!", sourceObjectiveStatus = "unverified-source-field" }
quests[10852] = { id = 10852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Friends", description = "We broke down here because some guys came in the night and made a lot of noise.  It was scary.  I don't know when we are going to get moving again.  \n\nSome of my friends are missing though.  I don't know where they are.  I think those scary bird men took them away to the northwest.  They probably are all locked up in cages and stuff.  If you find them that would be great.  I'm kind of worried about them.", sourceObjective = "Ethan wants you to find 12 of his missing friends in Veil Skith and then return to him at the Refugee Caravan.", progress = "I'm bored, there's nobody to play with.  Have you found my friends?", completion = "You found all my friends!  Now I have someone to play with.  Thank you, Mister {name}.  \n\nSince I have kids to play with maybe you would like one of my toys?  That way you have something to play with too.", sourceObjectiveStatus = "unverified-source-field" }
quests[10853] = { id = 10853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirit Calling", description = "The spirits of the nether drakes in the Singing Ridge are in need of liberation.\n\nThe nether drakes were not always nether drakes.  They used to be black drakes.\n\nBut then, with the destruction of this world, a wave of nether energy washed over everything and had the side-effect of changing the drakeling eggs.\n\nNow they are all twisted versions of their former selves.  We must help them to find peace.\n\nDo this by slaying a drake near to the spirit calling totem, and then take its spirit from it.", sourceObjective = "Use the Spirit Calling Totems to collect 8 Lesser Nether Drake Spirits.", progress = "The drakes of the Singing Ridge may pose a threat to us, but I think they are majestic creatures.\n\nOr, at least they were.  I hope that you will be able to save their spirits.\n\nAnd if you are in need of more totems, I have a few to spare.", completion = "You have done a good thing this day, {class}.  The spirits of the drakes will truly sing again now that they have been freed.  And the residual part of their spirits that they leave behind are powerful medicine, too.\n\nI wonder, are you up for a journey to the north?  There is something that I am curious about concerning the activities of the ethereal.\n\nI sense a great deal of pain coming from their direction.", sourceObjectiveStatus = "unverified-source-field" }
quests[10854] = { id = 10854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Force of Neltharaku", description = "Take this enchanted nethervine crystal and make your way back to Dragonmaw Fortress. Once there, seek out the enslaved drakes and invoke the magic of the nethervine crystal. My own energies will pour forth, causing the drakes to break free from the bond of their captors. When you see that the drake has broken free, help it defeat its captor! It will most assuredly be weak from the imprisonment.\n\nRelease all that you can find and return to me, {name}.", sourceObjective = "Neltharaku, flying high above Netherwing Fields in Shadowmoon Valley, wants you to free 5 Enslaved Netherwing Drakes.", progress = "Waste no time, we have much work to do!", completion = "<Neltharaku laughs.>\n\nThe orcs must have been shocked to see the drakes turn on them in such a manner. Well done, {name}. Perhaps you truly are the hero of our flight.", sourceObjectiveStatus = "unverified-source-field" }
quests[10855] = { id = 10855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Reavers, No Thanks!", description = "Ah, yes - the fel reaver!  Certainly the Legion's most terrible mechanical creation.  There are no less than three of these abominations aimed at the Stormspire.\n\nFortunately for us, they are not active yet.  This affords us the possibility of dealing with them through sabotage instead of brute force.\n\nObtain condensed nether gas from the gan'arg at Forge Base: Oblivion and fill a nearby fel reaver's fuel tank with it.  I've a feeling its engine won't handle it too well.", sourceObjective = "Obtain 5 Condensed Nether Gas from Gan'arg Mekgineers at Forge Base: Oblivion, northwest of the Stormspire, and load them into a nearby Inactive Fel Reaver. Return to Nether-Stalker Nauthis after you've completed this task.", completion = "That is excellent news, {name}.  Now that we know how to deal with these, I can have hirelings sabotage any remaining reavers.", sourceObjectiveStatus = "unverified-source-field" }
quests[10856] = { id = 10856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Best Defense", description = "Brave acts of industrial sabotage will only get us so far, {name}.  Just as Forge Base: Oblivion serves as an assembly site for Fel Reavers, Forge Base: Gehenna serves as a staging ground for their army as it is where the majority of the Legion's teleportation devices are located.\n\nI want you to go in there and put a dent in their numbers.  They must have a full regiment of wrathbringers by now and we just can't allow that.", sourceObjective = "Nether-Stalker Nauthis wants you to slay 12 Wrathbringers at Forge Base: Gehenna, north of the Stormspire.", progress = "How goes it?  Did you get a chance to show the Legion a lesson or two?", completion = "Nice work, {name}.  Keep it up and I'll put in a good word with the Nexus-Prince.", sourceObjectiveStatus = "unverified-source-field" }
quests[10857] = { id = 10857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teleport This!", description = "As fun as killing demons might be, it does us little good when the Legion can keep using its teleporters to replace anything we kill.\n\nUnfortunately, I don't have any high-powered explosives handy... but the mo'arg that maintain the teleporters do.\n\nTake this rod... I've tuned its powers to interfere with mo'arg brain frequencies.  Return to Forge Base: Gehenna and use it on any mo'arg you see.  You won't have long, but you'll be able to use their demolition charges on the nearby teleporters.", sourceObjective = "Nether-Stalker Nauthis wants you to use the Mental Interference Rod on the Mo'arg at Forge Base: Gehenna and use their Detonate Teleporter ability on the three teleporters in the forge camp.", progress = "Is it done then?  Are the teleporters shut down?", completion = "Thanks to you, {name}, I'll breathe a little easier.  Figure of speech, of course!\n\nI suppose you'll want some form of reward now.", sourceObjectiveStatus = "unverified-source-field" }
quests[10858] = { id = 10858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karynaku", description = "It shames me to ask for your assistance once more, {name}, but you are my flight's only hope. Without my mate, the netherwing brood may die out completely.\n\nMake your way to the top of Dragonmaw Fortress and find Karynaku.\n\nWe will be flying overhead. Should a break appear in their defenses, the might of the netherwing will swoop down to assist you.", sourceObjective = "Seek out Karynaku at Dragonmaw Fortress.", completion = "It is the chains. They sap my power. The only way is to get the key from Zuluhed and unbind me.", sourceObjectiveStatus = "unverified-source-field" }
quests[10859] = { id = 10859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gather the Orbs", description = "The Razaani ethereals have strange devices that emit small, pink floating light orbs.  They remind me of souls.\n\nThey are not to be confused with the large yellow balls that break free of the ethereal when they die, these are something else entirely.\n\nI'd like for you to head north to Razaan's Landing and drop some totems, which will attact the pink light orbs.\n\nBring them back to me so that I might determine exactly what they are.", sourceObjective = "Use the Orb Collecting Totem to collect 15 Razaani Light Orbs.", progress = "Have you collected all of the Razaani Light Orbs that are needed?", completion = "Something does not feel right.\n\nPlease, {name}, hand me the totem.  I must examine those orbs!", sourceObjectiveStatus = "unverified-source-field" }
quests[10860] = { id = 10860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mok'Nathal Treats", description = "Hungry, {race}?  The Great Spirit helps those that help themselves.  If you want to earn a meal, I suggest that you listen up, because Braagor there isn't going to give you anything for free, nor as tasty!\n\nThe raptors and scalewings of Razor Ridge and the Scalewing Shelf have everything that's needed for two of the most delicious dishes you'll ever taste.  Bring me their raptor ribs and serpent flesh, and I'll make some of each for you.\n\nI may even teach you how to cook them up for yourself, if you hurry.", sourceObjective = "Collect 3 Raptor Ribs and 3 Serpent Flesh.", progress = "Have all of the ingredients yet?  Talking about it with you has made my mouth water!", completion = "Mmm, I can taste them already.  Quickly, hand over those parts... I'm going to get them diced up and onto the fire!\n\nLuckily for you, this stuff keeps, and I mean for a long time!  So, take these, and I suppose you can have the recipes as well for being so kind as to restock my larder.", sourceObjectiveStatus = "unverified-source-field" }
quests[10861] = { id = 10861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veil Lithic: Preemptive Strike", description = "In the wretched colony to the southwest known as Veil Lithic, Terokk's minions are attempting to befoul their avian brethren before they hatch. The dark sorcerers of Lithic encase eggs in a shadowy curse. When the hatchlings emerge, they mindlessly serve Terrok.\n\nTravel to Veil Lithic and prematurely break the eggs before the curse has time to seep in. Even if you are too late, you can put down the tainted ones.\n\nRemember, the Light shines brightest in the darkness.", sourceObjective = "Break the cursed eggs in Veil Lithic. Redeem 3 Hatchlings and slay 3 Malevolent Hatchlings before returning to Kirrik the Awakened at the Refugee Caravan.", progress = "Have you done your bidding? Quash the evil before it is too late!", completion = "It is grim work toiling with someone's hatchlings, yet ignoring the brewing evil would be a bleak proposition as well. You have done well.  A'dal's favor shines upon your heart.", sourceObjectiveStatus = "unverified-source-field" }
quests[10862] = { id = 10862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surrender to the Horde", description = "The cowardly arakkoa attack us daily.  They ambush our hunters and sometimes even raid inside our walls.  We kill them when we can, but their magic is strong and they often escape our warbands.  \n\nI have learned that some arakkoa claim to be friendly with the Horde.  They live in Shattrath City to the northwest.  Rilak the Redeemed is their leader.  Search for him in the Lower City, and when you find him, demand his surrender.", sourceObjective = "Rokag wants you to seek out Rilak the Redeemed in the Lower City section of Shattrath City and demand that he and his people surrender to the Horde.", completion = "Your people are angry but there is little I can do.  Some of us have been touched by the power of the naaru and we are forever changed.  Those of us who remain in the wild are as we have always been.", sourceObjectiveStatus = "unverified-source-field" }
quests[10863] = { id = 10863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Arakkoa", description = "Out here on the frontier we have to deal with the arakkoa every day.  They strike at us when they please, raiding our supply lines and killing our scouts.  \n\nYet we know very little about these enigmatic creatures.  I have received news that northwest of here in Shattrath City there are arakkoa who are not hostile.  They might be willing to share the secrets of their race.  \n\nRilak the Redeemed is their leader.  He resides in the northern part of the Lower City.", sourceObjective = "Lady Dena Kennedy wants you to seek out Rilak the Redeemed in the Lower City section of Shattrath City and find out what secrets he will share of the Arakkoa.", completion = "You are wise to find me.  There is much that I can show you.", sourceObjectiveStatus = "unverified-source-field" }
quests[10864] = { id = 10864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Burden of Souls", description = "I have a device, the Demoniac Scryer, that can analyze fel magic.  I would have you use the Scryer, but first... you must appease it.  The Scryer, you see, has trapped within it a creature of vast intelligence and its needs are, shall we say, quite eccentric.\n\nTo appease the Scryer, you must kill orcs.  Specifically, they must be Shattered Hand orcs -- the Scryer demands their souls.\n\nReturn to me when the souls are reaped.  You will find the orcs north, and south, and surrounding... Hellfire Citadel.", sourceObjective = "Kill 20 Shattered Hand orcs, then return to Apothecary Antonivich in Thrallmar.", progress = "The Demoniac Scryer is not yet appeased, {name}.  Return to me after you have reaped the souls of Shattered Hand orcs.", completion = "Well done, {name}.  Your soul is burdened with many deaths... and the Demonaic Scryer will now perform its duties for you.\n\nLet us hope you are ready for the coming trial...", sourceObjectiveStatus = "unverified-source-field" }
quests[10865] = { id = 10865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inform Leoroxx!", description = "Quickly, you must inform Leoroxx of what is transpiring up at Razaan's Landing!\n\nThose orbs were comprised of souls, some of them Mok'Nathal!", sourceObjective = "Speak with Leoroxx about what the Razaani ethereal are up to. He can be found at Mok'Nathal Village in the Blade's Edge Mountains.", completion = "What you say, is it even possible?  What am I saying?  Of course it is, if the spiritcallers say so.\n\nRemember before when I said that we might need your further assistance?  It would seem that I can tell the future.", sourceObjectiveStatus = "unverified-source-field" }
quests[10866] = { id = 10866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuluhed the Whacked", description = "He hides in my thoughts, mortal. He waits for me to break... for me to bend to his will.\n\nAnd this will be his undoing. I will call for him. I will tell him that I will do as he asks. When he appears, kill him and take the key!\n\nKnow this: Zuluhed is an ancient orc with unknown powers. He has surely been empowered further by Illidan. You risk your life for me in doing as I ask. Are you certain you wish to make such a sacrifice?", sourceObjective = "Kill Zuluhed the Whacked and recover Zuluhed's Key. Use Zuluhed's Key on Zuluhed's Chains to free Karynaku.", progress = "<Karynaku groans.>", completion = "I am free! You have saved us, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[10867] = { id = 10867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There Can Be Only One Response", description = "There can be only one response to this... this, DEFILEMENT of the souls of our ancestors!\n\n{name}, if you would aid us to restore the souls of our honored dead to their rightful place, go back to Razaan's Landing.\n\nGo back up there and kill the razaani until their leader, Nexus-Prince Razaan shows his cowardly face.  Kill him and get those souls back, and then give them over to Spiritcaller Dohgar!", sourceObjective = "Collect the Collection of Souls.", progress = "Have you done it?  Are the souls of our ancestors safely recovered from the evil of the ethereals?", completion = "Good that the ethereal filth and their leader are dead.  I wish a thousand plagues upon their brethren!\n\nYou are to be rewarded for you actions on behalf of all of the Mok'Nathal, {name}!  You are truly one of our heroes.\n\nLet us now release the souls of our ancestors to the cleansing fire.", sourceObjectiveStatus = "unverified-source-field" }
quests[10868] = { id = 10868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arakkoa War Path", description = "The arakkoa have attacked us again, this time striking in the night and then using their dark magic to escape before we could charge out to meet them in numbers.  They use their summoning circles to rescue their warriors from certain death but they cannot run from us if we attack their homes.  Veil Reskk and Veil Shienor lie to the north and northeast.  \n\nFind these arakkoa nests and kill as many as you can.", sourceObjective = "Advisor Faila asks that you kill 14 Shienor Talonites and 6 Shienor Sorcerers and then return to her in Stonebreaker Hold.", completion = "Well done {class}.  The arakkoa have learned to fear the might of the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[10869] = { id = 10869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thin the Flock", description = "The arakkoa have attacked us again, this time striking in the night and then using their dark magic to escape before we could marshal our soldiers.  \n\nVeil Reskk and Veil Shienor lie to the north and northwest.  Find these arakkoa nests and kill as many as you can.  They may not fear us, but at least we can thin their numbers.", sourceObjective = "Lieutenant Gravelhammer asks that you kill 14 Shienor Talonites and 6 Shienor Sorcerers and then return to him in Allerian Stronghold.", completion = "Well done {class}.  The arakkoa have learned to fear the might of the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[10870] = { id = 10870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ally of the Netherwing", description = "Allow me to return you to Mordenai. I am certain that he wishes to see you once more.", sourceObjective = "Let Karynaku return you to Mordenai in the Netherwing Fields.", completion = "You have proven yourself as an ally of the Netherwing. My mother is free and my brothers and sisters are saved!\n\nPerhaps someday, we will call for you again. When that day comes, know that you will be welcomed with open arms - a brother to the Netherwing Dragonflight.", sourceObjectiveStatus = "unverified-source-field" }
quests[10871] = { id = 10871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ally of the Netherwing", description = "Allow me to return you to Mordenai. I am certain that he wishes to see you once more.", sourceObjective = "Let Karynaku return you to Mordenai in the Netherwing Fields.", completion = "You have proven yourself as an ally of the Netherwing. My mother is free and my brothers and sisters are saved!\n\nPerhaps someday, we will call for you again. When that day comes, know that you will be welcomed with open arms - a brother to the Netherwing Dragonflight.", sourceObjectiveStatus = "unverified-source-field" }
quests[10872] = { id = 10872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuluhed the Whacked", description = "He hides in my thoughts, mortal. He waits for me to break... for me to bend to his will.\n\nAnd this will be his undoing. I will call for him. I will tell him that I will do as he asks. When he appears, kill him and take the key!\n\nKnow this: Zuluhed is an ancient orc with unknown powers. He has surely been empowered further by Illidan. You risk your life for me in doing as I ask. Are you certain you wish to make such a sacrifice?", sourceObjective = "Kill Zuluhed the Whacked and recover Zuluhed's Key. Use Zuluhed's Key on Zuluhed's Chains to free Karynaku.", progress = "<Karynaku groans.>", completion = "I am free! You have saved us, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[10873] = { id = 10873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taken in the Night", description = "Our small outpost is under constant attack. Several nights ago, we were raided by the spiders of Netherweb Ridge, on the southeastern edge of the Bone Wastes. They poisoned many of our people, wrapped them in webs and carried them away. Some of our warriors took up arms and with little preparation pursued the spiders.\n\nWe have not seen the captives or our hunting parties since. We hope that some may still be alive, perhaps imprisoned by the spiders.  Our numbers are few. Will you search for our people?", sourceObjective = "Scout Navrin wants you to travel to the Netherweb Ridge and free 6 Webbed Sha'tar Warriors and then return to him at Sha'tari Base Camp.", progress = "Did you find our missing people?", completion = "You saved so many.  I didn't think we would ever see them again.  We cannot thank you enough, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10874] = { id = 10874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veil Shalas: Signal Fires", description = "Terokk's perch, Skettis, looms above the Bone Wastes to the east. At the base of Skettis lies Veil Shalas, the most formidable of Terokk's colonies. It is through the stronghold of Veil Shalas that Terokk's forward sages wage war against the Light.\n\nThe evil-doers of Shalas communicate with their master using a complex system of magical signal fires. Travel to the east, {race}, and extinguish the fires. Once Veil Shalas is silenced, we can begin to plot the fall of Skettis.\n\nBut I get ahead of myself.", sourceObjective = "Kirrik the Awakened at the Refugee Caravan wants you to extinguish the four signal fires of Veil Shalas.", progress = "Veil Shalas must be silenced!", completion = "We witnessed the cursed smoke rise from here. You are most brave, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10875] = { id = 10875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Nazgrel", description = "{name}, during your foray with the Demoniac Scryer, I sent word of your exploits against the fel orcs.  Nazgrel, our illustrious leader in Thrallmar, wishes to speak with you.  I believe he has a bloody mission in mind...", sourceObjective = "Speak with Nazgrel at Thrallmar in Hellfire Peninsula.", completion = "It is good to hear of all your moves against the fel orcs, {name}.  The apothecaries have spent much time and resources studying the cause of their corruption, and although such information in invaluable... my orc blood burns to strike a severe blow against these betrayers!\n\nListen close, and I will explain my task...", sourceObjectiveStatus = "unverified-source-field" }
quests[10876] = { id = 10876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Foot of the Citadel", description = "Force Commander Gorax is training Shattered Hand captains at the base of Hellfire Citadel, honing them to a bloody razor's edge.  You must kill him, {name}, for his loss would be a mighty blow to the fel orcs.\n\nHowever, that is not all you must do.\n\nTake this banner.  Place it atop Gorax's corpse.  Gorax's commander, the Hand of Kargath, must answer your challenge if he has even a drop of true orc blood within him!\n\nHis head, the head of the hand of Kargath, is what I seek.", sourceObjective = "Kill Force Commander Gorax, place the Challenge From the Horde upon his corpse, kill The Hand of Kargath, and then bring the Head of the Hand of Kargath to Nazgrel in Thrallmar.", progress = "Have you faced the Hand of Kargath, {name}?", completion = "You have done a great deed, {name}.  The fel orcs are a shame to all true orcs.  If we have one fear, it is the fear of  succumbing to demonic corruption once again.  So you see, our war against the fel orcs is more than merely a battle with fierce foes -- it is also a battle within ourselves.\n\nAnd with strength, strength you have shown time again, it is a battle we will win.", sourceObjectiveStatus = "unverified-source-field" }
quests[10877] = { id = 10877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dread Relic", description = "Long ago a caravan went to Auchindoun with a mission to take a Dread Relic from the ancient tombs beneath the necropolis. They fled, but the relic was their undoing.  The relic is evil and it summons evil when touched.   Their caravan was destroyed somewhere to the east. \n\nThis dark artifact is the key to a terrible plan to defeat Teribus the Cursed, a creature that flies over the Bone Wastes.  Help me if you wish, but your life and even your soul will be at risk.", sourceObjective = "Oakun wants you to travel east to the Derelict Caravan to recover the Dread Relic. Return to Oakun when the task is complete.", progress = "Do you have the Dread Relic?  We must have it.", completion = "It is incredible that you succeeded.  The Dread Relic is far more powerful than I feared. Only a mighty hero could have survived the long journey back carrying such blasphemous evil.", sourceObjectiveStatus = "unverified-source-field" }
quests[10878] = { id = 10878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Before Darkness Falls", description = "After our caravan fell prey to an attack by Shadow Council cabal cultists, scouts were sent to Shattrath to call for help.  The guards think we're safe for now, but they underestimate these madmen.\n\nI, for one, am not looking forward to having my throat slit by some cabal initiate in the middle of the night.  Do us all a favor and take the fight to them, before they come to us.\n\nYou will find our attackers south of here, at Auchindoun's northern entrance.", sourceObjective = "Mekeda at the Refugee Caravan wants you to kill 8 Cabal Skirmishers, 4 Cabal Spell-Weavers and 2 Cabal Initiates.", progress = "Have you done what I asked of you, {name}?  I fear for our lives.", completion = "I can breath a sigh of relief for now, {name}.  The Shadow Council will be held off for the time being.\n\nThey are murderers and cowards and your display of courage will keep them at bay.", sourceObjectiveStatus = "unverified-source-field" }
quests[10879] = { id = 10879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Skettis Offensive", description = "Skettis has waged war on us! Have you gathered enough to help with Shattrath's defense?\n\nHold off the attackers!", sourceObjective = "Hold off the attackers and speak with Rilak the Redeemed.", progress = "This is no time for idle chatter, {name}. We're under attack! Hold off the invaders!", completion = "I applaud your prowess in combat, {class}. You have proven yourself to be a true defender of the Light. May A'dal's blessing shine upon your darkest hours.\n\nBut look far into the horizon. Dark skies loom above Skettis. Terokk is undoubtedly plotting his next move. Shattrath is safe for now. But only tomorrow knows what terror will descend upon us.", sourceObjectiveStatus = "unverified-source-field" }
quests[10880] = { id = 10880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cabal Orders", description = "This message bears a dark seal and though the language seems somewhat familiar, it appears to be encoded.\n\nPerhaps someone at the Refugee Caravan will know something about it.", sourceObjective = "Bring the Cabal Orders to Mekeda at the Refugee Caravan in the Bone Wastes.", progress = "You wish to show me something, {name}?", completion = "Ah, yes... this was written in a basic form of the shadow cypher.  My knowledge of it is not perfect but it should suffice to translate this.\n\nYou learn much about unsavory subjects when you live among outcasts and refugees in the Lower City.", sourceObjectiveStatus = "unverified-source-field" }
quests[10881] = { id = 10881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow Tomb", description = "Many believe it was the Shadow Council that caused the explosion that tore Auchindoun apart.  It is rumored they awoke a great evil inside.\n\nIf that is true, then that evil must have turned against them.  According to these orders, part of the Shadow Council is fleeing Auchindoun.  They are using the Shadow Tomb to store powerful artifacts from Auchindoun.\n\nThree of these are sacred, for they belonged to the powerful patriarchs Arunen, K'alen and Atalor.  I must ask you to retrieve them.", sourceObjective = "Go into the Shadow Tomb, west of the Refugee Caravan and retrieve the Drape of Arunen, the Gavel of K'alen and the Scroll of Atalor. Return to Mekeda at the Refugee Caravan after you've completed this task.", progress = "Have you retrieved the relics, {name}?  We cannot allow the Shadow Council to use their power for dark purposes.", completion = "The Light might have forgotten me, but I have not forgotten the Light.  These relics were once very sacred to my people.\n\nAllowing the Shadow Council to use their power for evil is... unthinkable!", sourceObjectiveStatus = "unverified-source-field" }
quests[10882] = { id = 10882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harbinger of Doom", description = "<A discordant note can be detected in A'dal's 'voice'.>\n\nPrince Kael'thas has chosen his warden poorly, and now the entities that we kept locked up within the Arcatraz are breaking free.\n\nOne in particular, a servant of the Old Gods known as Harbinger Skyriss, seeks to usher in his masters' vision of conquering all of the worlds in the universe.\n\n{name}, you must not allow him to escape.  Return to Tempest Keep, enter the Arcatraz, and slay Harbinger Skyriss before it is too late!", sourceObjective = "You have been tasked to go to Tempest Keep's Arcatraz satellite and slay Harbinger Skyriss. Return to A'dal at the Terrace of Light in Shattrath City after you have done so.", progress = "<A'dal focuses his attention upon you, his gaze almost unbearable.>\n\n{name}, perhaps you do not understand the magnitude of your mission?  There is no time to waste... gather yourself a group of compatriots and enter the Arcatraz.\n\nPut an end to Harbinger Skyriss.", completion = "<The crystalline timber of A'dal's voice carries a more tranquil melody within your mind than the last time the two of you spoke.>\n\nOnce again you have proven your mettle.  Had Harbinger Skyriss broken free, countless thousands would have perished in the ensuing conflict, just as happened with another servant of the Old Gods, Skeram, on your world of Azeroth.\n\n{name}, what I have to offer in return may seem a pittance in comparison, but know that it comes with the everlasting gratitude of the Sha'tar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10883] = { id = 10883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tempest Key", description = "You have proven yourself capable of great feats, {name}. Your discovery of the Cipher of Damnation and Kael'Thas' involvement is most important to our cause. Should Kael use the cipher, what little is left of this world may collapse.\n\nA'dal is convinced that Kael must be stopped and now seeks adventurers willing to undergo trials. Those that prove their strength will be granted favor by the naaru.\n\n<Khadgar nods.>\n\nA'dal awaits...", sourceObjective = "Speak with A'dal in Shattrath City.", completion = "Tempest Keep is a naaru creation, mortal. Access to the vessel has always been within our power to grant. A return to Tempest Keep, though, had been deemed unnecessary. A point of pride for a mortal race, perhaps, but naaru invest little in such things.\n\nWe go now because we must. Kael'thas cannot be allowed to utter the words of damnation.\n\nWhile the way is open, only a fool would enter unproven. Do not underestimate the purpose of the trials, mortal.", sourceObjectiveStatus = "unverified-source-field" }
quests[10884] = { id = 10884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial of the Naaru: Mercy", description = "Four trials you must pass before you are deemed worthy by the naaru.\n\nWithin the Shattered Halls of Hellfire Citadel are three of your people. They are held there by the merciless one, Kargath Bladefist. He seeks to execute them as a sign of his virility and power. You must save these prisoners before such an atrocity can come to pass. As proof of deed, bring me the unused axe of the executioner. It must not have a drop of blood on its blade!", sourceObjective = "A'dal in Shattrath City wants you to recover the Unused Axe of the Executioner from the Shattered Halls of Hellfire Citadel.\n\nThis quest must be completed in Heroic dungeon difficulty.", progress = "<A'dal greets you.>", completion = "Well done, {name}. You have passed the trial of mercy.", sourceObjectiveStatus = "unverified-source-field" }
quests[10885] = { id = 10885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial of the Naaru: Strength", description = "Four trials you must pass before you are deemed worthy by the naaru.\n\nThe trial of strength is divided in two. You must destroy the leader of the Coilfang Steamvaults, Warlord Kalithresh, and bring me his trident. Slay the extra-planar being known as Murmur, in the Shadow Labyrinth of Auchindoun, and bring me his essence.\n\nDo this and you will have passed the trial of strength.", sourceObjective = "A'dal in Shattrath City wants you to recover Kalithresh's Trident and Murmur's Essence.\n\nThis quest must be completed in Heroic dungeon difficulty.", progress = "<A'dal greets you.>", completion = "Well done, {name}. You have passed the trial of strength.", sourceObjectiveStatus = "unverified-source-field" }
quests[10886] = { id = 10886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial of the Naaru: Tenacity", description = "Four trials you must pass before you are deemed worthy by the naaru.\n\nIn our travels we have encountered many dangerous beings. Some of these beings we incarcerated and placed in what is now known as the Arcatraz of Tempest Keep.\n\nThere is one prisoner, however, that is a victim of circumstance. A stowaway who was in the wrong naaru vessel at the wrong time.\n\nVenture to the Arcatraz and rescue the gnome, Millhouse Manastorm. Ensure his survival.", sourceObjective = "A'dal in Shattrath City wants you to rescue Millhouse Manastorm from the Arcatraz of Tempest Keep.\n\nThis quest must be completed in Heroic dungeon difficulty.", progress = "<A'dal greets you.>", completion = "Well done, {name}. You have passed the trial of tenacity.", sourceObjectiveStatus = "unverified-source-field" }
quests[10887] = { id = 10887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escaping the Tomb", description = "I appreciate your help, {name}.  I was certain I was going to be killed.\n\nLet's get out of here with a hurry.  It won't be long before more cultists come after us.", sourceObjective = "Help Akuno find his way to the Refugee Caravan. Speak to Mekeda after you've completed this quest.", completion = "You rescued Akuno, a dear friend of mine.  For this I am in your debt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10888] = { id = 10888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial of the Naaru: Magtheridon", description = "Four trials you must pass before you are deemed worthy by the naaru.\n\nOnly one obstacle remains, mortal. Gather an army and travel to the lair of Magtheridon, deep inside Hellfire Citadel. Battle your way to the heart of the chamber and destroy the foul corrupter!", sourceObjective = "A'dal in Shattrath City wants you to slay Magtheridon.", progress = "<A'dal greets you.>", completion = "You have proven yourself as a being of great power. The naaru approve...", sourceObjectiveStatus = "unverified-source-field" }
quests[10889] = { id = 10889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Shattrath", description = "Your actions, while brave, will surely rouse a vindictive response from Terokk.\n\nHurry to Shattrath. Send word to Rilak!", sourceObjective = "Travel to Shattrath City and speak with Rilak the Redeemed in the Lower City.", completion = "The guardians of Skettis grow restless from their perch. Shattrath is in trouble. We will surely feel the brunt of Terokk's revenge.\n\nMuster a defense party quickly! Speak with Defender Grashna and let him know you are ready to bear arms against our attackers!", sourceObjectiveStatus = "unverified-source-field" }
quests[10891] = { id = 10891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperial Plate Armor", description = "There's a dwarf in Gadgetzan by the name of Derotain Mudsipper who'll teach you how to make imperial plate armor. All you gotta do is get to the Tanaris desert and find him. Interested?", sourceObjective = "Speak with Derotain Mudsipper at Gadgetzan in Tanaris.", completion = "Of course I'll teach you how to make imperial plate armor! It might cost you a bit of gold... in the form of thorium bars!", sourceObjectiveStatus = "unverified-source-field" }
quests[10892] = { id = 10892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperial Plate Armor", description = "There's a dwarf in Gadgetzan by the name of Derotain Mudsipper who'll teach you how to make imperial plate armor. All you gotta do is get to the Tanaris desert and find him. Interested?", sourceObjective = "Speak with Derotain Mudsipper at Gadgetzan in Tanaris.", completion = "Of course I'll teach you how to make imperial plate armor! It might cost you a bit of gold... in the form of thorium bars!", sourceObjectiveStatus = "unverified-source-field" }
quests[10893] = { id = 10893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Longtail is the Lynchpin", description = "With the Blackwing wyrmcultists massing in the tunnel, we're hard pressed to deal with the situation.  Quite frankly, they have the numbers.\n\nAnd while we've been able to take care of any of their people that get too close, the fact remains that if they attack in earnest, we're going to be overrun.\n\nThe situation calls for someone to get through to the other end of the tunnel, and take out their leader, Draaca Longtail.  Up for some fun?", sourceObjective = "Slay Draaca Longtail, the leader of the wyrmcultists in the Wyrmskull Tunnel.", progress = "Is she dead?\n\n{name}, if we're to have a fighting chance here, we need you to sow confusion into their ranks by killing Draaca Longtail!", completion = "With Draaca out of the picture, we should be able to take advantage of the situation.  They'll be in-fighting over who should be in charge, and that will relieve some of the pressure.\n\nThat is, unless the overseer mentioned in that note you gave me comes to take her place.\n\nLet's see if you can do something to make sure that never happens!", sourceObjectiveStatus = "unverified-source-field" }
quests[10894] = { id = 10894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wyrmskull Watcher", description = "Hmm, I'm not certain what we should do.  I'm not much of a military planner.\n\nWatcher Moonshade will know what to do.  He's heading up our defensive efforts at the Wyrmskull Tunnel to the west at the end of Wyrmskull Bridge.  We have a force out there just in case the cultists try anything funny.\n\nPlease, take the note to him with all due haste.", sourceObjective = "Deliver the Meeting Note to Watcher Moonshade at the entrance of the Wyrmskull Tunnel in the Blade's Edge Mountains.", progress = "How can I help you?  You bring news from Evergrove?", completion = "It's as I thought, and that's not good!\n\nI've got an idea for how to help you, but first, I was wondering if you might help us out?\n\nYou scratch my back, I'll scratch yours.", sourceObjectiveStatus = "unverified-source-field" }
quests[10895] = { id = 10895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeth'Gor Must Burn!", description = "It's time to strike Zeth'Gor from the air!  Our gryphon riders are ready for a sortie, {name}.  But they need someone on the ground to direct their fire.  Are you ready for a covert mission?\n\nTake these smoke beacons into Zeth'Gor, the Bleeding Hollow stronghold to the west.  They have four guard towers: one near their northern wall, one near their southern wall, one near their forge and another nestled in their foothills.  Place a beacon underneath each of the towers and we'll fly in and bomb them!", sourceObjective = "Use the smoke beacon at each of Zeth'Gor's towers, and then return to Wing Commander Dabir'ee at Expedition Point.", progress = "Time is crucial, {name}.  We need those guard towers burned!", completion = "I could see the smoke and flames from here!  Good job, {name}!  You received more than a few words of praise from our gryphon riders -- what you just did took a lot of guts...", sourceObjectiveStatus = "unverified-source-field" }
quests[10896] = { id = 10896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Infested Protectors", description = "The trees of this land are ravaged by the power that was unleashed from Auchindoun.  The foul magic that was unleashed blasted the land into the wastes you see all around.  The trees that survived are now infested with wretched wood mites that crawl under their bark and gnaw at their flesh.  \n\nRotting forest-rages and infested root-walkers are breeding grounds for the mites.  They are found along the edge of the wood to the east.  Destroy these creatures and then kill the mites that flee their husks.", sourceObjective = "Lakotae wants you to kill 25 Wood Mites and then return to him at the Refugee Caravan. The mites can be found living inside the bodies of Rotting Forest-Ragers and Infested Root-Walkers.", progress = "Have you destroyed the worst of the infestations?", completion = "You have done much to help Terokkar Forest, {name}.  With the worst of the mite colonies destroyed we may yet be able to reclaim this wasted land.", sourceObjectiveStatus = "unverified-source-field" }
quests[10897] = { id = 10897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master of Potions", description = "As you know, plants have properties that allow alchemists to re-energize and reinvigorate others through potions.\n\nMy familiarity with the plants of Outland allows me to teach alchemists how to make the most out of them.  If you're interested in expanding your knowledge of potions, I have but one task to ask of you.\n\nHigh Botanist Freywinn in Tempest Keep is rumored to have written a comprehensive botany guide.  Bring it to me along with samples of your work and I'll teach you the knowledge you seek.", sourceObjective = "Lauranna Thar'well wants you to go to the Botanica in Tempest Keep and retrieve the Botanist's Field Guide from High Botanist Freywinn. In addition she also wants you to bring her 5 Super Healing Potions, 5 Super Mana Potions and 5 Major Dreamless Sleep Potions.\n\n*WARNING!* You can only select one alchemy specialization.", progress = "Are you sure about this, {name}?  Specializing in potions will prevent you from pursuing other specializations.", completion = "Excellent!  It looks like you're eager to learn, so let's get to it.  I will teach you how to make the most out of the plants you use in your alchemical potions.\n\nYou will find that you can make herbs go a really long way if you know what you're doing.  Sometimes you will be able to make two potion with materials you initially judged necessary for just one.", sourceObjectiveStatus = "unverified-source-field" }
quests[10898] = { id = 10898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skywing", description = "Skywing flutters around you.\n\nYou get the feeling he wants you to follow him.", sourceObjective = "Escort Skywing and report to Rilak the Redeemed in Shattrath City.", completion = "Alas, poor Skywing was under the dreaded curse of Luanga the Imprisoner!\n\nSkywing traveled to Veil Shalas to attempt to sway others in seeing the way of the Light. They didn't take lightly to his actions, especially sitting on the doorstep of Skettis.\n\nLuanga was one of Terokk's most feared agents. You have done well by freeing Skywing! I thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[10899] = { id = 10899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master of Transmutation", description = "Any alchemist will tell you that matter is malleable, any substance can be transformed into another - but nothing is really created or destroyed.\n\nA true master of transmutation can learn to overcome this limitation - and I can teach you how to obtain this mastery!\n\nAs a prospective transmuter you're undoubtedly familiar with primal might - the combination of the material representation of all primal forces.  Show me proof of your transmuting prowess and I will share my knowledge with you.", sourceObjective = "Zarevhi at the Stormspire in Netherstorm wants you to bring him 4 Primal Mights.\n\n*WARNING!* You can only select one alchemy specialization.", progress = "Are you sure you want to become a master transmuter?  If you specialize in this field you will find it impossible to specialize in potions or elixirs.", completion = "Excellent work, {name}!  These transmutations are perfect in every way!\n\nI will now teach you the manner in which the alchemical transmutation process can conjure matter out of thin air!  Make good use of your knowledge, master transmuter.\n\nNow, if you'll excuse me, I have to go see a buyer interested in primal might.", sourceObjectiveStatus = "unverified-source-field" }
quests[10900] = { id = 10900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mark of Vashj", sourceObjective = "Burn it down, {race}. Burn it all down! They deserve nothing! Do you hear me! NOTHING! They must pay for what they have done. For what they continue to do.\n\nI would kill Vashj myself if I could break free of these damned bindings.\n\nOr maybe you seek to do the work of Neptulon? Her death serves both of us, soft-skin. Will you assist me in forming the sacred cudgel.", sourceObjectiveStatus = "unverified-source-field" }
quests[10901] = { id = 10901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cudgel of Kar'desh", description = "Bring me the elemental signets that the cudgel requires!\n\nThe earthen signet is held by Gruul the Dragonkiller. Gruul can be found inside his lair in the Blade's Edge Mountains.\n\nThe second signet is the blazing heart of a creature known as Nightbane. This mythical beast is said to reside in the hallowed halls of the prophet, Medivh.\n\nMake haste!", sourceObjective = "Skar'this the Heretic in the heroic Slave Pens of Coilfang Reservoir wants you to bring him the Earthen Signet and the Blazing Signet.", progress = "With the cudgel reformed, I shall break free of my bonds and return to Serpentshrine to exact vengeance on Vashj and her minions!", completion = "At last!\n\nWith these bonds broken and the cudgel in my possession I shall send  the sea witch back to the icy depths...", sourceObjectiveStatus = "unverified-source-field" }
quests[10902] = { id = 10902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master of Elixirs", description = "I've devoted my life to perfecting my elixirs.  Despite my success, I haven't been able to create an elixir of eternal life.\n\nI think I know the reagent I'm missing.  I've heard of a place called the Caverns of Time in Azeroth where intruders known as rift lords and rift keepers phase in and out of the timeline.\n\nThis intrusive time-shifting creates tears in time itself, twisting it infinitely into crystallized essences.  Bring these to me along with samples of your work and I'll teach you all I know.", sourceObjective = "Go to the Black Morass in the Caverns of Time and obtain 10 Essences of Infinity from Rift Lords and Rift Keepers. Bring these along with  5 Elixirs of Major Defense, 5 Elixirs of Mastery and 5 Elixirs of Major Agility to Lorokeem in Shattrath's Lower City.\n\n*WARNING!* You can only select one alchemy specialization.", progress = "The essences!  Do you have them?", completion = "You are very good with elixirs, if these are any indication.  You will make a fine student.\n\nThese essences will provide me enough materials to formulate my recipe.  I will be known among all alchemists for this discovery!\n\nNow, if you're willing to learn, I am willing to teach.", sourceObjectiveStatus = "unverified-source-field" }
quests[10903] = { id = 10903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Honor Hold", description = "{name}, while you were on your mission in Zeth'Gor, I received news of my commanding officer, Colonel Jules.  He was stricken with a demonic corruption while fighting near the Gor'gaz Outpost, and his situation has grown very bad.\n\nYou have made such great gains for us against the fel orcs.  Your strength in battle is without question... is your spirit just as strong?\n\nPlease, return to Honor Hold and speak with Klatu, in an upper room at the Honor Hold inn.", sourceObjective = "Speak with Assistant Klatu, at Honor Hold's inn.", completion = "Yes, it is true.  Colonel Jules' situation has grown much worse these past days.  Anchorite Barada is busy praying for him... let us hope he may be cured.", sourceObjectiveStatus = "unverified-source-field" }
quests[10904] = { id = 10904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harvesting the Fel Ammunition", description = "We must shut down the Burning Legion's access to Death's Door, but first you're going to destroy their two warp-gates!\n\nThe problem is, we can't even scratch one of those things, so you're going to need to use their own weapons against them.\n\nThe death's might, death's watch, deathforge over-smiths and deathforge technicians carry the ammunition for the fel cannons.\n\nNormally it wouldn't affect any of them, but if you bring the cannonballs to me, I will imbue them with Nature's unbridled wrath!", sourceObjective = "Collect 5 Fel Cannonballs.", progress = "Do you have the cannonballs yet?", completion = "Those things stink more than I thought they would!\n\nQuickly, hand them over to me and I will imbue them with Nature's force such that they will prove extremely deadly to their fel masters and their unnatural creations.", sourceObjectiveStatus = "unverified-source-field" }
quests[10905] = { id = 10905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master of Potions", description = "My knowledge of alchemy is vast.  It is, however, general in nature.  If you wish to specialize, you will have to find others who have narrower fields of study.\n\nIf you wish to specialize in potion creation, I would recommend that you seek the help of Lauranna Thar'well of the Cenarion Expedition.\n\nHer knowledge of plants will allow you to make the most of your raw materials.  Look for her in Zangarmarsh and tell her I sent you to her.", sourceObjective = "Speak to Lauranna Thar'well at Cenarion Refuge in Zangarmarsh.\n\n*WARNING!* You can only select one alchemy specialization.", completion = "You want me to help you with your study of potions?  Very well, {name}.  Let's see what we can do.", sourceObjectiveStatus = "unverified-source-field" }
quests[10906] = { id = 10906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master of Elixirs", description = "My knowledge of alchemy is vast.  It is, however, general in nature.  If you wish to specialize, you will have to find others who have narrower fields of study.\n\nIf you wish to specialize in elixir creation, I would recommend that you seek the help of the arakkoa known as Lorokeem.\n\nHis knowledge of elixirs is unmatched, yet he  squanders his skill pursuing an elixir of eternal life.  Find him and see what he can teach you.", sourceObjective = "Speak to Lorokeem in Shattrath's Lower City.\n\n*WARNING!* You can only select one alchemy specialization.", completion = "You want to learn from me?  Hmmm, yes.  Perhaps you'll be a suitable student.", sourceObjectiveStatus = "unverified-source-field" }
quests[10907] = { id = 10907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master of Transmutation", description = "My knowledge of alchemy is vast.  It is, however, general in nature.  If you wish to specialize, you will have to find others who have narrower fields of study.\n\nIf you wish to specialize in transmutation, I would recommend that you seek the help of the ethereal known as Zarevhi.  He resides in the Stormspire in Netherstorm.\n\nHis mastery of transmutation is... well, outlandish!  See what you can learn from him, but beware - ethereals drive a hard bargain.", sourceObjective = "Speak to Zarevhi at the Stormspire in Netherstorm.\n\n*WARNING!* You can only select one alchemy specialization.", completion = "You want me to help you with your study of transmutations?  Very well, {name}.  Let's see what we can do.", sourceObjectiveStatus = "unverified-source-field" }
quests[10908] = { id = 10908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Rilak the Redeemed", description = "You look surprised to be talking to me. I do not blame you. My people, the arakkoa, deserve to be feared.\n\nSpeak with Rilak the Redeemed in Shattrath City if you wish to know more. He can be found in the northern part of the Lower City, with the other outcasts of Skettis.\n\nAnd, {name}, we will speak again.", sourceObjective = "Kirrik the Awakened wants you to speak with Rilak the Redeemed in the Lower City section of Shattrath City.", completion = "So we meet, {name}. You must forgive the lack of formalities for time is of the essence.", sourceObjectiveStatus = "unverified-source-field" }
quests[10909] = { id = 10909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Spirits", description = "Colonel Jules was cursed in a battle near the Gor'gaz Outpost, a haunt for Shattered Hand fel orcs.  My master, Barada, works feverishly to cure the poor human, but he needs help.  The Colonel's tormented spirit seeks peace, and his path to peace is, I fear, a path of vengeance.\n\nTake this anchorite relic to Gor'gaz Outpost.  Place it upon the ground near Shattered Hand orcs and defeat them.  This will release their fel spirits -- you must slay those fel spirits for Jules' own spirit's recovery.", sourceObjective = "Klatu in Honor Hold wants you to use the Anchorite Relic at Gor'gaz Outpost southwest of Honor Hold, slay Shattered Hand Berserkers near the relic, and then slay 10 released Fel Spirits to avenge Colonel Jules.", progress = "The fel spirits of the Shattered Hand orcs are a blight to poor Jules' soul.  Tell me, {name}... has he been appeased?", completion = "The Shattered Hand orcs are foul and beyond hope, but my heart is saddened that the road to salvation for Colonel Jules holds such bloodshed.", sourceObjectiveStatus = "unverified-source-field" }
quests[10910] = { id = 10910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death's Door", description = "Now there is an even greater threat from the Burning Legion.  To the south is a portal known as Death's Door, which opens upon the horrific world where the Legion breeds its deadly hounds.\n\nTo get there, exit Evergrove by heading east up the ramp.  Follow the path south, through the Bladed Gulch, Razaan's Landing, Razor Ridge and the Scalewing Shelf.  Then, take the ramp down into the Vekhaar Stand and enter Death's Door through the tunnel, south of Mok'Nathal.\n\nOnce there, use this druid signal.", sourceObjective = "Use the Druid Signal at Death's Door to call down and speak with an Evergrove Druid.\n\nProvided item:", completion = "It is a relief that Wildlord Antelarion has sent you to us.  The problem is much worse than first we feared!", sourceObjectiveStatus = "unverified-source-field" }
quests[10911] = { id = 10911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire At Will!", description = "Now that the ammunition can affect the Burning Legion, it's time for you to use it.\n\nThere are two warp-gates, which are used for teleportation and enhancement of the void terrors.  One is in the south and the other in the north, and each is within range of a fel cannon.\n\nUse the naturalized ammunition to take control of each fel cannon and destroy the warp-gates.\n\nAttack the gate with artillery to begin, and be prepared to kill its defenders to keep the cannon alive if necessary.", sourceObjective = "Use the Naturalized Ammunition to take control of the Death's Door Fel Cannons. Use the cannons to destroy both the South Warp-Gate and the North Warp-Gate.", progress = "Have you destroyed both of the warp-gates yet?", completion = "Your prowess is staggering!\n\nVery well, with the warp-gates out of the picture, there's only one thing left to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[10912] = { id = 10912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hound-Master", description = "Baelmon the Hound-Master must die!  He maintains the ritual that keeps the portal functioning.\n\nThe Death's Door portal is located at the north end of the canyon.  When you find it, you will find Baelmon.\n\nYou're going to need help on this one, so take this wand.  When you battle the Hound-Master, use it and a couple of my friends will come to your aid.\n\nAfter you have defeated Baelmon, return to Wildlord Antelarion.\n\nAnd, {name}, thank you for all that you've gone through for us here.", sourceObjective = "Slay Baelmon the Hound-Master.", progress = "It is over then?  Has the danger at Death's Door been averted?", completion = "You are truly an amazing {race}!  If I thought that we were indebted to you before, then now there is simply no way in which we could ever repay you.\n\nBut we'll give it a try.  Thank you, hero of Evergrove!", sourceObjectiveStatus = "unverified-source-field" }
quests[10913] = { id = 10913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Improper Burial", description = "Is there nothing that can be done to stem the tide of corruption? My soldiers have been battling the Auchenai for days now with no end in sight. Each casualty, whether Auchenai or Sha'tar, is snatched from the battlefield - their souls lifted and taken to parts unknown.\n\nI will not have it! A proper burial is out of the question but those fiends will not have their souls! Take this torch and travel to the field of battle, directly east of here. Burn every corpse you see! We will not fuel their rituals.", sourceObjective = "Commander Ra'vaj at the Sha'tari Outpost in the Bone Wastes of Terokkar Forest wants you to burn 8 Slain Auchenai Warriors and 8 Slain Sha'tar Vindicators.", progress = "It's a terrible thing to ask, I know...", completion = "<Commander Ra'vaj holds his head in his hands.>\n\nIt's not enough... It's just not enough.", sourceObjectiveStatus = "unverified-source-field" }
quests[10914] = { id = 10914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero Is Needed", description = "It is not enough. A hero is needed. Our forces are overwhelmed as the Auchenai continue to grow in number.\n\n<Commander Ra'vaj looks at you.>\n\nWill you be the hero? Return to the field of battle and strike at their soldiers. Keep them occupied so that my scouts can get behind their lines and see what they are creating.", sourceObjective = "Commander Ra'vaj at the Sha'tari Outpost in the Bone Wastes of Terokkar Forest wants you to slay 12 Auchenai Initiates and 5 Auchenai Doomsayers.", progress = "Take no prisoners!", completion = "You've done it, {name}! Because of you, we have made a new discovery...", sourceObjectiveStatus = "unverified-source-field" }
quests[10915] = { id = 10915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fallen Exarch", description = "They are feeding the souls they steal to a coffin that they have dragged out from the Auchenai Crypts. My scouts believe the contents of the coffin to contain the first exarch of the crypts. They seek to resurrect the ancient one!\n\nYou must battle your way to the western side of Auchindoun and disturb the contents of that coffin before they feed it enough souls. Should you lose your way, follow the walking souls.\n\nDestroy whatever is inside that coffin!", sourceObjective = "Commander Ra'vaj at the Sha'tari Outpost in the Bone Wastes of Terokkar Forest wants you to destroy the contents of the Auchenai Coffin.", progress = "You must destroy the ancient evil before it has regained its powers.", completion = "Victory is ours! This defeat will set the Auchenai back several weeks.", sourceObjectiveStatus = "unverified-source-field" }
quests[10916] = { id = 10916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Digging for Prayer Beads", description = "Anchorite Barada plans to exorcise the corruption from Colonel Jules, and will require an assistant for the task.  Such an assistant must be prepared...\n\nI am ashamed to admit that my prayer beads were lost in Honor Hold's courtyard.  I believe the dog Fei Fei stole them and buried them, but I do not know where.  If you speak with his master, Warrant Officer Tracy Proudwell, perhaps she will know where Fei Fei hides his stolen treasures.", sourceObjective = "Recover the Draenei Prayer Beads and bring them to Assistant Klatu in Honor Hold.", progress = "Have you found the prayer beads, {name}?  Their powers are crucial to many holy rites... including the rite of exorcism.", completion = "You found the prayer beads!  Well done, {name}.  You are a wonder, indeed -- you slay the horrors of Hellfire Peninsula one moment and find lost treasures the next.  Your people truly inspire!\n\nIt is good that you recovered these beads... for they will be invaluable in the exorcism ritual to come.", sourceObjectiveStatus = "unverified-source-field" }
quests[10917] = { id = 10917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Outcast's Plight", description = "As an outcast, I am marked by death by arakkoa loyal to the city of Skettis.  I cannot leave these walls for fear of my life, but that doesn't mean I cannot strike at them in retaliation.\n\nI have a small cache of treasure that I'm willing to part with, should you help me strike back at my would-be assassins.  Bring me feathers from the denizens of the various Veils of Terokkar as proof of their demise.", sourceObjective = "Bring 30 Arakkoa Feathers to Vekax in Shattrath's Lower City.", progress = "Do you bring the feathers I asked for, {name}?", completion = "<Vekax squawks in glee as you present him with proof of his enemies' demise.>\n\nYes, that will show Skettis that we Outcasts will not take their punishment lying down.  Here is the reward I promised you.  I can arrange for more, should you provide me with additional feathers.", sourceObjectiveStatus = "unverified-source-field" }
quests[10918] = { id = 10918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Feathers", progress = "Skettis's lapdogs still keeps a close watch over us, outcasts.  The moment any of us sets foot outside Shattrath we'll be as good as dead.\n\nBring me more feathers as proof of your victory over them.", completion = "<Vekax squawks in glee as you present him with proof of his enemies' demise.>\n\nYes, that will show Skettis that we Outcasts will not take their punishment lying down.  Here is the reward I promised you.  I can arrange for more, should you provide me with additional feathers.\n\n<This quest can be repeated up to Honored reputation.>" }
quests[10919] = { id = 10919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fei Fei's Treat", progress = "Fei Fei looks at you expectantly...", completion = "<Fei Fei barks happily and grabs the doggy treat.  He looks left and right... deciding where he should hide this new treasure...>" }
quests[10920] = { id = 10920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For the Fallen", description = "When the dreadfang widows attacked our outpost we heard the voice of the naaru calling us to battle.  We pursued the creatures into the night.  Some of our people we found dead in the dark, others we could hear struggling against their captors. \n\nBy morning we had come to this place and we fought a fierce battle but we were beaten.  Dreadfang poison will soon take my companions and I cannot last long.  Before I die I must know that the dreadfang widows were beaten.", sourceObjective = "Vindicator Haylen wants you to slay 20 Dreadfang Widows and then return to him just west of Netherweb Ridge.", progress = "I can feel the poison flowing through my veins.  The naaru call to me, I can see the light.  Are the dreadfang widows defeated?", completion = "I heard the sounds of your battle from here, {class}.  The sounds of your victory filled my heart with hope.  If you can win against such terrible odds, perhaps I can find the strength to drag my companions from this terrible place.", sourceObjectiveStatus = "unverified-source-field" }
quests[10921] = { id = 10921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terokkarantula", description = "You have slain many of the dreadfang widows but they will continue to spawn and soon they will strike at us again.  Deep within Netherweb Ridge is the lair of the Terokkarantula, the brood-mother of these gruesome creatures.  If we are to be safe, she must die.", sourceObjective = "Vindicator Haylen wants you to kill the Terokkarantula and then return to him west of Netherweb Ridge.", progress = "Has Terokkarantula been slain?", completion = "The dreadfangs are beaten.  You have killed many and even their foul mother has fallen before you.  I am too poisoned to fight my way to freedom.  \n\nPlease, take some of my equipment.  It will lighten my load and give you the tools you need to make the journey back to Sha'tar Outpost.", sourceObjectiveStatus = "unverified-source-field" }
quests[10922] = { id = 10922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Digging Through Bones", description = "Oy! You look like you can take care of yerself, {race}. Me and the crew here are looking for a bodyguard to watch over us while we hit a dig site to the north. The pay is pretty good and all you gotta do is make sure no nasty creatures kill me or any of my employees.\n\nIf you successfully make it back without any casualties, Dwarfowitz over there will pay ya.", sourceObjective = "Escort Letoll and his crew and protect them while they make their dig. Return to Dwarfowitz at the Sha'tari Outpost if you succeed.", progress = "You get paid when the job is done, sonny.", completion = "A bone wurm! Fantastic! This may actually be the first time in recorded history that Letoll has actually made a discovery.", sourceObjectiveStatus = "unverified-source-field" }
quests[10923] = { id = 10923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evil Draws Near", description = "Now you must use the Dread Relic in a foul necromantic ritual if you wish to challenge Teribus the Cursed.  To the northeast, beyond Auchindoun, is the Writhing Mound, a place where necromancers gather.  \n\nThe auchenai death-speakers and doomsayers carry doom skulls that are laced with powerful necro-enchantments.  If you collect enough skulls you can use their power along with the power of the Dread Relic to command Teribus to face you.", sourceObjective = "Oakun wants you to take the Dread Relic to the Writhing Mound. Once there, kill Auchenai Death-Speakers and Auchenai Doomsayers to collect 20 Doom Skulls. Then find the Writhing Mound Summoning Circle and use the Dread Relic to summon and destroy Teribus the Cursed. Return to Oakun when the deed is done.", progress = "Has Teribus the Cursed been purged from the skies of Terokkar?", completion = "A great evil has been cleansed from Terokkar.  The Sha'tar are in your debt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10924] = { id = 10924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloody Imp-ossible!", description = "The blood of the warp chasers in this area is a powerful and rare reagent. It's one of my biggest sellers.\n\nNormally, I take my imp, Zeppit, out to help me gather it. Warp chaser blood is simply too caustic to be handled safely by you or I, but it doesn't bother Zeppit.\n\nThings are getting busier here at the shop, so if I send Zeppit with you, will you help gather the blood? Zeppit's attention tends to wander, so you'll need to be close to the chaser when it dies for Zeppit to do his work.", sourceObjective = "Bring 8 vials of Warp Chaser Blood to Sab'aoth at Cosmowrench.", progress = "Did Zeppit cooperate enough for you to get all the blood I'll need?", completion = "This should prove a large enough supply for my needs.\n\nI hope the imp didn't give you too much trouble. He has a bit of a nasty mouth on him.", sourceObjectiveStatus = "unverified-source-field" }
quests[10925] = { id = 10925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evil Draws Near" }
quests[10926] = { id = 10926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Sha'tari Base Camp", description = "We will not make it back on our own.  The dreadfang poison is too strong. You must return to Sha'tari Base Camp for us.  Scout Navrin will send a rescue party out to find us.", sourceObjective = "Vindicator Haylen wants you to return to the Sha'tari Base Camp in the Bone Wastes and speak with Scout Navrin.", completion = "It is good to know that some of our warriors fought well against the dreadfang widows.  We will send a rescue party immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[10927] = { id = 10927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Killing the Crawlers", description = "Commander Skyshadow wants this tunnel cleared out so we can expedite trade with the Harborage. I must not leave my post here so I am leaving the task in your hands. Clear the tunnel and report to Commander Skyshadow at once!", sourceObjective = "Slay 6 Cavern Crawlers.", completion = "Good work, {class}. That tunnel is our lifeline to the swamp.", sourceObjectiveStatus = "unverified-source-field" }
quests[10928] = { id = 10928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Killing the Crawlers", description = "Tor'chunk Twoclaws wants this tunnel cleared out so we can expedite trade with Swamp Rat. I must not leave my post here so I am leaving the task in your hands. Clear the tunnel and report to Tor'chunk Twoclaws at once!", sourceObjective = "Slay 6 Cavern Crawlers.", completion = "Good work, {class}. That tunnel is our lifeline to the swamp.", sourceObjectiveStatus = "unverified-source-field" }
quests[10929] = { id = 10929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fumping", description = "How would you like to do a little more work for the Explorers' League? These bone worms have us all quite intrigued.\n\nI've got a drum right here that you can use out in the Bone Wastes. Just bang on the damned thing and see what you get. If it's a worm, kill it and bring back the carcass for us to study. We'll need a good lot of carcasses to get a valid testing sample.", sourceObjective = "Dwarfowitz at the Sha'tari Base Camp in the Bone Wastes wants you to bring him 8 Mature Bone Sifter Carcasses.", progress = "We think the one that popped up at the dig was actually a baby worm!", completion = "Sand gnomes? Yea, sure... The desert can do strange things to a person.\n\nI think we're about to make a breakthrough here with these worms!", sourceObjectiveStatus = "unverified-source-field" }
quests[10930] = { id = 10930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Big Bone Worm", description = "I was right! These carcasses you brought me belong to the baby bone worms. Do you know what that means? It means that somewhere out there is a big one! I think we can get it to come out if we can provide the right kind of food. Let's see... something big! Yes!\n\nI remember seeing clefthooves east of here on the other side of the Bone Wastes. Get out there and kill a clefthoof. Once it's dead, use the drums. Hopefully the big one will come up to feed. If you manage to kill it, bring me its organs!", sourceObjective = "Dwarfowitz at the Sha'tari Base Camp in the Bone Wastes wants you to recover Enormous Bone Worm Organs.\n\nHe wants his Fumper back too.", progress = "Take a friend with you!", completion = "Amazing! Look at this stuff! The thing-a-ma-whatever has some sort of dust inside its whatcha-ma-bobber. Bah! I won't bore you with all this scientific jargon. I did manage to pull a few teeth from the little ones to make these incredibly sharp knives. Want one?", sourceObjectiveStatus = "unverified-source-field" }
quests[10931] = { id = 10931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Exodar", description = "Your master Caedmos of the Exodar has requested to see you.  It concerns your training, but I don't really know anything beyond that.", sourceObjective = "Speak with Caedmos at the Exodar.Your master Caedmos of the Exodar has requested to see you. It concerns your training, but I don't really know anything beyond that.", sourceObjectiveStatus = "unverified-source-field" }
quests[10932] = { id = 10932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Exodar", description = "Your master Caedmos of the Exodar has requested to see you.  It concerns your training, but I don't really know anything beyond that.", sourceObjective = "Speak with Caedmos at the Exodar.Your master Caedmos of the Exodar has requested to see you. It concerns your training, but I don't really know anything beyond that.", sourceObjectiveStatus = "unverified-source-field" }
quests[10933] = { id = 10933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Silvermoon", description = "Your master Aldrae in Silvermoon City has requested to see you.  It concerns your training, but I don't really know anything beyond that.", sourceObjective = "Speak with Aldrae in Silvermoon City.Your master Aldrae in Silvermoon City has requested to see you. It concerns your training, but I don't really know anything beyond that.", sourceObjectiveStatus = "unverified-source-field" }
quests[10934] = { id = 10934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Silvermoon", description = "Your master Aldrae in Silvermoon City has requested to see you.  It concerns your training, but I don't really know anything beyond that.", sourceObjective = "Speak with Aldrae in Silvermoon City.Your master Aldrae in Silvermoon City has requested to see you. It concerns your training, but I don't really know anything beyond that.", sourceObjectiveStatus = "unverified-source-field" }
quests[10935] = { id = 10935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Exorcism of Colonel Jules", description = "{name}, it is time to save Colonel Jules.  His condition has worsened and Barada fears that, if we do not cleanse him of his corruption,  he will be lost to us.\n\nTake the prayer beads you found and speak with Anchorite Barada to begin the ritual.  Let no disruptions stop the ritual... and if all goes well, Colonel Jules will be saved.  Speak with Jules when he is saved, then return to me.", sourceObjective = "Speak with Anchorite Barada. Use the prayer beads to help with the ritual, and then speak with Colonel Jules when he is saved. Finally, return to Assistant Klatu.", progress = "Go to Anchorite Barada, {name}.  He must succeed with his ritual if the colonel is to be saved.", completion = "You have done it, {name}.  You have saved Colonel Jules' soul and cast the darkness within him back to where it came.  A great, noble deed this is!  A hero's day!", sourceObjectiveStatus = "unverified-source-field" }
quests[10936] = { id = 10936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollbane is Looking for You", description = "While we were busy, a messenger was waiting out in the hall.  I suppose he grew tired, or perhaps he simply ran away at the sight of Jules floating around the room.\n\nEither way, Force Commander Danath is looking for you.  I suggest that you seek an audience with him inside the barracks as quickly as possible!", sourceObjective = "Assistant Klatu has informed you that Force Commander Danath Trollbane has been seeking you. Speak to him in the barracks at Honor Hold in Hellfire Peninsula.", completion = "It's about time!  I heard all about what you've been up to with that draenei priest. You totally freaked my messenger out!\n\nNow that you're done with that, I have a little mission planned for you to Hellfire Citadel.", sourceObjectiveStatus = "unverified-source-field" }
quests[10937] = { id = 10937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drill the Drillmaster", description = "I'm receiving reports that the Shattered Hand fel orcs, out in front of Hellfire Citadel, are organizing for what looks like an all-out assault.  No doubt, they're not happy about your successes against all of the clans.\n\nGet to the base of the citadel, where the Path of Glory ends.  You'll find the fel orcs busy with their preparations, but you're going to catch them with their pants down.\n\nEliminate the one that's in charge of that force.  Kill Drillmaster Zurok!", sourceObjective = "Force Commander Danath Trollbane has ordered you to kill Drillmaster Zurok with all due haste. Return to the force commander at Honor Hold in the Hellfire Peninsula once the drillmaster is dead.", progress = "Is the drillmaster dead?  Hmm, maybe my scouts are wrong?", completion = "I wasn't going to believe it until I heard it from you, personally.  Already our scouts are trickling in with information that the Shattered Hand are in disarray without their precious drillmaster to tell them what to do.\n\nYou've traveled a long road, {name}.  I trust that you will accept this armor along with my thanks.  Wear it proudly, you've earned it!", sourceObjectiveStatus = "unverified-source-field" }
quests[10938] = { id = 10938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Blessings Deck", description = "Now that you have gathered all of the Blessings cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"   You have heard that this faire alternately stops at Mulgore and Goldshire every few months, so you will have to wait until they are here next.", sourceObjective = "Return the Blessings Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of Blessings!   Congratulations!", completion = "So you have put together a deck of Blessings.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[10939] = { id = 10939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Storms Deck", description = "Now that you have gathered all of the Storms cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"   You have heard that this faire alternately stops at Mulgore and Goldshire every few months, so you will have to wait until they are here next.", sourceObjective = "Return the Storms Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of Storms!   Congratulations!", completion = "So you have put together a deck of Storms.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[10940] = { id = 10940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Furies Deck", description = "Now that you have gathered all of the Furies cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"   You have heard that this faire alternately stops at Mulgore and Goldshire every few months, so you will have to wait until they are here next.", sourceObjective = "Return the Furies Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of Furies!   Congratulations!", completion = "So you have put together a deck of Furies.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[10941] = { id = 10941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Lunacy Deck", description = "Now that you have gathered all of the Lunacy cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"   You have heard that this faire alternately stops at Mulgore and Goldshire every few months, so you will have to wait until they are here next.", sourceObjective = "Return the Lunacy Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of Lunacy!   Congratulations!", completion = "So you have put together a deck of Lunacy.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[10942] = { id = 10942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Children's Week", description = "One special little girl is going to be very happy to have you as a friend, even if it is for a short while.\n\nTake this whistle.  With it, you will be able to call for the child that you have agreed to sponsor.  It will only last for a limited time - not much longer than Children's Week itself, in fact.\n\nPlease, {name}, call upon your orphan.  I know that she will be more than excited to meet you and have the opportunity to venture out of the city!", sourceObjective = "Use the Blood Elf Orphan Whistle to call for the ward that you will be looking after during Children's Week.\n\nProvided item:", completion = "Hmph, you're my sponsor?  I'm Salandria!  I've been here ever since I was a little baby.  My parents were taken by the war, so I have to live here at the orphanage.\n\nIt's not that bad, but I always wanted to go places -- I haven't ever stepped foot outside of the city.  I've already made a list of all the cool places that I want to go, and the awesome things that I want to do.\n\nI'm ready to go when you are!", sourceObjectiveStatus = "unverified-source-field" }
quests[10943] = { id = 10943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Children's Week", description = "One special little girl is going to be very happy to have you as a friend, even if it is for a short while.\n\nTake this whistle.  With it, you will be able to call for the child that you have agreed to sponsor.  It will only last for a limited time - not much longer than Children's Week itself, in fact.\n\nPlease, {name}, call upon your orphan.  I know that she will be more than excited to meet you and have the opportunity to venture out of the city!", sourceObjective = "Use the Draenei Orphan Whistle to call for the ward that you will be looking after during Children's Week.\n\nProvided item:", completion = "You must be the adventurer who's going to be my big brother for Children's Week!  I'm Dornaa, pleased to meet you.\n\n<She looks sad for a moment.>\n\nMother and father were killed in the war, and I've lived in the orphanage all my life.  It's nice, actually, but I've always wanted to go places and see things.\n\nI've already made a list of places we could visit, if that's okay?  I just know that we're going to have a great time together!\n\nI'm ready to go when you are!", sourceObjectiveStatus = "unverified-source-field" }
quests[10944] = { id = 10944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Secret Compromised", description = "Thanks again, {name}.  I recognize your name.  Akama has entrusted you with his plans and so I will trust you as well.\n\nThe naga discovered I was working against Illidan and tried to get me to speak by torturing me.  I did not tell them a thing - Akama himself taught me to master pain through meditation.\n\nIllidan asked the naga to bring me to him.  He would have seen right through my flesh and into my soul's deepest secrets.\n\nAkama must be warned.  Our plans are in jeopardy!", sourceObjective = "Travel to the Warden's Cage in Shadowmoon Valley and speak to Akama.", completion = "I thank you, {name}.  Olum is one of my dearest friends and most trusted followers.  His contributions have been of vital importance to our plans.", sourceObjectiveStatus = "unverified-source-field" }
quests[10945] = { id = 10945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hch'uu and the Mushroom People", description = "I had a friend named Hch'uu.  She told me that she ended up in the orphanage because she had to run away from an evil fungal giant and got lost.\n\nWe had great fun until her people came and took her away last year.  I think she said she was going to live at a place called Sporeggar.\n\nI'd like to go to see her and have a look at her mushroom village.  The orphan matron told me that it is on the west side of Zangarmarsh, between the Sporewind and Marshlight lakes.\n\nCan we go?  Can we go?  Please?!", sourceObjective = "Take your orphan, Salandria, to Sporeggar in Zangarmarsh. Make sure to call for her if she is not present when you arrive. Then, speak with Hch'uu.", completion = "Thank you for this chance to once again see Salandria.  I have missed her so much this past year, but we are still good friends.\n\nWe agreed that when we grow up, we're both going to be brave adventurers, just like you!", sourceObjectiveStatus = "unverified-source-field" }
quests[10946] = { id = 10946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruse of the Ashtongue", description = "Olum's sacrifice was tremendous.  I would never have asked him to give up his life myself.  But it is done.\n\nIf we're to lure Illidan back into a false sense of security, we need to do his bidding - at least for now.\n\nI command a vast army of Ashtongue, but - aside from the Deathsworn - none can be trusted.\n\nYou are to perform the deed that Illidan demands.  Take this cowl; it is magical in nature.  You will appear to be one of my men to any who see you slaying Kael's phoenix, Al'ar.", sourceObjective = "Travel into Tempest Keep and slay Al'ar while wearing the Ashtongue Cowl. Return to Akama in Shadowmoon Valley once you've completed this task.", progress = "Is the deed done, {name}?  Illidan is not a patient master!", completion = "You've done well, {name}.  This will bring us a step closer to shifting Illidan's focus away from us and from...\n\n\n\nMore work remains to be done, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10947] = { id = 10947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Artifact From the Past", description = "Illidan's attention is now on Kael'thas, thanks to you.  The time has come to make our move.\n\nI've had a vision of an artifact that will aid us in our final struggle - the phylactery of a lich known as Winterchill.  Unfortunately its power was lost forever after his defeat in the Battle of Mount Hyjal.\n\nThere might be a way to retrieve this artifact, however.  Legend speaks of a place in Azeroth guarded by bronze dragons...  a place where past and present meet.  It is there you will find what we seek.", sourceObjective = "Go to the Caverns of Time in Tanaris and gain access to the Battle of Mount Hyjal. Once inside, defeat Rage Winterchill and bring the Time-Phased Phylactery to Akama in Shadowmoon Valley.", progress = "Have you retrieved the phylactery yet, {name}?", completion = "My vision... it all becomes clear now.  The powers this artifact has over a soul.... to contain it... to siphon it into itself... I will use those powers to reclaim what belongs to me!  The time has arrived for us to take the fight to Illidan!", sourceObjectiveStatus = "unverified-source-field" }
quests[10948] = { id = 10948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hostage Soul", description = "You might wonder why I go to such lengths to hide my intentions.  Why not throw my lot in openly with the naaru?\n\nMy very essence - my soul - is held prisoner inside the Black Temple.  Illidan could destroy me any moment... until now!  This phylactery will allow me to regain control of my soul.\n\nThe time has come, {name}.  I'll lead Maiev and my Deathsworn to Illidan's doorstep.\n\nSpeak to A'dal and and tell him of our plan.  If we strike together we'll break through Illidan's defenses.", sourceObjective = "Travel to Shattrath City to tell A'dal about Akama's request.", completion = "<A'dal's light surrounds you as he welcomes you back.  You have a feeling he knows what you're about to ask of him.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10949] = { id = 10949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entry Into the Black Temple", description = "<A'dal shows you an image of a naaru outside of the Black Temple, fighting alongside draenei vindicators and blood elf magisters.  You immediately understand that this is the distraction Akama is waiting for.>", sourceObjective = "Travel to the entrance to the Black Temple in Shadowmoon Valley and speak to Xi'ri.", completion = "<Xi'ri appears to acknowledge your presence.  He seems to be focused on the battle in the surrounding area.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10950] = { id = 10950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auchindoun and the Ring of Observance", description = "One of the priests that comes to visit told a story about a place nearby.  It's called Auchindoun, and it's supposed to be very important to the draenei.\n\nHe said it used to be the place where the bodies of the draenei were taken when they died.  But some time ago, something bad blew it up.\n\nI'd like to see its Ring of Observance.  The orphan matron told me that it is in the middle of the Bone Wastes, on the south side of the Terokkar Forest.\n\nPlease, <Mr./Miss> {name}, can we go?", sourceObjective = "Take your orphan, Dornaa, to the Meeting Stone at the Ring of Observance in the middle of Auchindoun. Auchindoun, in turn, is in the middle of Terokkar Forest's Bone Wastes. Make sure to call for her if she is not present when you arrive.", completion = "Oh, it's just wonderful!  I mean, it looks pretty old... and yeah, someone sure did blow it up.  But just look at it!\n\nOoh, and did you look up at the sky?\n\nNeato!", sourceObjectiveStatus = "unverified-source-field" }
quests[10951] = { id = 10951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Trip to the Dark Portal", description = "How can we look at all of these interesting places and not see the Dark Portal?!\n\nThe grown-ups are always trying to tell us scary stories about it and how it's so dangerous, with lots of demons, and stuff.\n\n<Salandria rolls her eyes.>\n\nBut you're here, so it can't be too bad, right?\n\nI want to see for myself.  You remember where it is on the east edge of Hellfire Peninsula?", sourceObjective = "Take your orphan, Salandria, up the steps of the Stair of Destiny to stand before the Dark Portal in Hellfire Peninsula. Make sure to call for her if she is not present when you arrive.", completion = "The stories don't even come close to how cool this place is.  It's amazing!\n\nIs it true that a powerful wizard named Medivh created it?\n\nI wonder what's on the other side?  You've been there, right?  Hmm, we should definitely go someplace on the other side of the Dark Portal!", sourceObjectiveStatus = "unverified-source-field" }
quests[10952] = { id = 10952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Trip to the Dark Portal", description = "There's one place that if we don't go anywhere else, we have to go to: the Dark Portal!\n\nThe orphan matrons are always trying to scare us with stories about how dangerous it is, with lots of demons, and people like you coming through it.\n\n<Dornaa rolls her eyes.>\n\nBut you're here, and nice, so it can't be too bad, right?\n\nI want to see it for myself.  You remember where it is on the eastern edge of Hellfire Peninsula?", sourceObjective = "Take your orphan, Dornaa, up the steps of the Stair of Destiny to stand before the Dark Portal in Hellfire Peninsula. Make sure to call for her if she is not present when you arrive.", completion = "The orphan matron's stories don't even come close to how cool this place is.  It's amazing!  She said that it was created by a powerful wizard named Medivh.\n\nWhat's on the other side of it?  You've been there, right?  We should most definitely go someplace on the other side of the Dark Portal!", sourceObjectiveStatus = "unverified-source-field" }
quests[10953] = { id = 10953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visit the Throne of the Elements", description = "Have you heard of the Throne of the Elements?  It's supposed to be this place in Nagrand where there are these powerful elementals.\n\nOne day soon, I'm going to be a powerful mage, or maybe a warlock.  I'm gonna have to learn about some of the elemental forces!\n\nDo you think maybe that we could go there?\n\n<Salandria looks at you slyly.>\n\nYa know, it would be educational to go there.  It's supposedly just north of Garadar, on the other side of Skysong Lake.", sourceObjective = "Take your orphan, Salandria, to the Throne of the Elements in Nagrand. Make sure to call for her if she is not present when you arrive. Then, speak with Elementalist Sharvak.", completion = "You bring a child here?  Foolhardy, but I promise that she will come to no harm, at least as long as she doesn't get too close to Incineratus.\n\nHmm, unfortunate that she's a blood elf.  Were she capable of a deep connection to the world, we could teach her some things so that she might aid us to heal its wounds.  But, perhaps her exposure to the elements here will give her some insight into their workings.\n\nGo in peace and see to it that you take good care of her.", sourceObjectiveStatus = "unverified-source-field" }
quests[10954] = { id = 10954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jheel is at Aeris Landing!", description = "I miss my brother, Jheel.  He's a couple of years older than me, so they let him start an apprenticeship with the ethereal in Nagrand.\n\nIt sure would be nice to go visit him.  He loves geology and stuff, so I bet he's having a great time.\n\nThe orphan matron told me that he's training at a place called Aeris Landing in Nagrand.  It's supposed to be along the road, far to the west of Telaar, and northwest of the great mountain, Oshu'gun.", sourceObjective = "Take your orphan, Dornaa, to Aeris Landing in Nagrand. Make sure to call for her if she is not present when you arrive. Then, speak with Jheel.", completion = "Oh, I've missed Dornaa so much.  Thank you for bringing her to visit.  It gets lonely here with only the ethereal around.  And they're so serious all the time with this Oshu'gun business.\n\nBut I get to go back and visit the orphanage after I pass my gemcutting exams.  I almost passed them last week, but I'm sure that I'll do better on the test tomorrow!", sourceObjectiveStatus = "unverified-source-field" }
quests[10955] = { id = 10955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morthis Whisperwing", description = "Before all of the druidic orders coalesced into the Cenarion Circle, the Druids of the Talon were responsible for teaching promising young druids the mysteries of flight. With the dissolution of the order, former members teach the skill sparingly.\n\nEven now, Morthis Whisperwing continues his search for a suitable apprentice. Few druids have truly mastered all the forms available to them, but you show the promise Morthis requires of his students. Seek him out at the Cenarion Refuge in Zangarmarsh.", sourceObjective = "Seek out Morthis Whisperwing at the Cenarion Refuge in Zangarmarsh.", completion = "<Morthis considers you somewhat skeptically.>\n\nI have long searched for an apprentice to pass my knowledge to. Though the Druids of the Talon are no longer a formal group, I shall remain one to the last of my days.\n\nI accept you as my apprentice from this moment forward. For my part, I will teach you the secrets of the stormcrow. For your part, you must be prepared to do all I ask. Do you understand?", sourceObjectiveStatus = "unverified-source-field" }
quests[10956] = { id = 10956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Seat of the Naaru", description = "Do you know anything about the naaru?  They're these angelic beings that have been helping the draenei for a really long time.  I've seen a bunch around Shattrath.\n\nThey say that one naaru, O'ros, was with the Exodar when it traveled to your homeworld.  I should like to see for myself.\n\nCan you take me there?  I bet we could get there fast by using one of the portals inside the Terrace of Light at Shattrath City!  When we get there, if you get lost, we could always just look at your map.", sourceObjective = "Take your orphan, Dornaa, to stand before O'ros at the bottom of the Seat of the Naaru inside of the Exodar, which is on Azuremyst Isle. Make sure to call for her if she is not present when you arrive.\n\nRemember that you can use your map inside the city.", completion = "<You feel, more than hear, the musical voice of O'ros chiming in your mind.>\n\nThank you for bringing this child to me, {name}.  She is very special indeed, and will grow up one day to be an important figure amongst the draenei.  This is in no small part due to the kindness that you have shown her, and the impression that you have made.", sourceObjectiveStatus = "unverified-source-field" }
quests[10957] = { id = 10957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redemption of the Ashtongue", description = "When Illidan obtained the Broken's allegiance, Akama was our wisest.  He knew that openly opposing the Betrayer would lead to the extinction of our race.\n\nInstead he has plotted and schemed for this very moment under utmost secrecy.  Failure would be catastrophic... not just for Akama, not just for the Broken, but for all of Outland.  No one this close to Illidan has ever been able to deliver such a terrible blow to him.\n\nHelp Akama free his soul and he will grant you access to Illidan's sanctum.", sourceObjective = "Help Akama wrest control back of his soul by defeating the Shade of Akama inside the Black Temple. Return to Seer Kanai when you've completed this task.", progress = "Yes, {name}?", completion = "It is done, {name}.  The time to strike at Illidan has come.", sourceObjectiveStatus = "unverified-source-field" }
quests[10958] = { id = 10958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek Out the Ashtongue", description = "<As you look up at Xi'ri, your mind becomes focused and your will determined.  Your work here is not done; you must go inside the Black Temple and find Akama's followers.>\n\n<Much depends on Akama's success.>", sourceObjective = "Find Akama's Deathsworn inside the Black Temple.", completion = "We've been expecting you, {name}.  Akama is in great need of your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[10959] = { id = 10959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of the Betrayer", description = "With Illidan's lieutenants defeated, Akama will be able to force open the doors to Illidan's sanctum.  Be ready to bring your force inside as soon as Akama does.\n\nWe still do not know what has become of Maiev, but we must make our move without her.\n\nI hope your force is up to the task.  Illidan will not be pleased to see Akama.", sourceObjective = "Seer Kanai wants you to defeat Illidan inside the Black Temple.", progress = "Yes, {name}?", completion = "It is as it was foretold, {name}.  One by one, Illidan's lieutenants have fallen... and now the Betrayer himself has met his demise!\n\nKnow this, {name}: every decision Akama made and every moment of his life since Illidan arrived, Akama planned for this moment.  Illidan is finally dead and our people... are free!", sourceObjectiveStatus = "unverified-source-field" }
quests[10960] = { id = 10960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When I Grow Up...", description = "When you were my age did you know that you wanted to be a {class} when you grew up?\n\nI'm not sure what I want to be.  Maybe a mage or a warlock, like I said before?  Or maybe a paladin Blood Knight?  Yeah, definitely a Blood Knight!\n\nThey say that the true ones are trained in Silvermoon City on your world.  Could you take me there?  The stories that I've heard say that the paladin trainers reside in the Farstriders' Square in that city.\n\nPlease take me there.  Please!", sourceObjective = "Take your orphan, Salandria, to the paladin trainers in Silvermoon City's Farstriders' Square. Make sure to call for her if she is not present when you arrive. Then, speak with Lady Liadrin, the Blood Knight Matriarch.\n\nRemember that you can use your map inside the city, and speak to the guards to find the paladin trainers.", sourceObjectiveStatus = "unverified-source-field" }
quests[10961] = { id = 10961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ward of Wakening", description = "Long ago, the relics used to teach the ways of the stormcrow were entrusted to an ancient druid.\n\nYour training requires these relics, so we must wake their guardian from his slumber.\n\nI will prepare a potion you can use to ease the process. The mixture requires common herbs, as well as bogblossom, which usually grows atop the tallest mushrooms in the marsh. Fly up there and pursue them but take care, as they're quite fragile and may explode violently if mishandled.", sourceObjective = "Bring 10 Bogblossoms, 10 Ancient Lichen, and 10 Dreaming Glory to Morthis Whisperwing at the Cenarion Refuge.", progress = "Have you brought the ingredients for the draught? Take care not to get pollen on me, please. I sneeze uncontrollably in its presence.\n\n<Morthis sniffs at the indignity represented by a sneeze.>", completion = "<Morthis accepts the herbs from you, inspecting them. Producing a vial, he begins mixing the potion.>\n\nThis will only take a moment, {name}. Then, you must travel to Moonglade.", sourceObjectiveStatus = "unverified-source-field" }
quests[10962] = { id = 10962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time to Visit the Caverns", description = "In the orphanage, the old priest that comes by told us stories about the Caverns of Time.  He said that it sits in the middle of time, and is really important for keeping things straight.\n\nI don't know what that means, but he said that there were dragons there that were helping to save the world!  I want to see a dragon!\n\nDo you think that we could go there?  He said that the entrance was on the eastern edge of a great desert named Tanaris.\n\nMaybe you could buy me a souvenir while we're there?", sourceObjective = "Take your orphan, Dornaa, to stand before Zaladormu, the dragon on the dais in the middle of the Caverns of Time. Make sure to call for her if she is not present when you arrive.\n\nThen, purchase a Toy Dragon for her from the Keepers of Time Quartermaster, Alurmi, near the bottom of the entrance tunnel.", progress = "You think it's true what they say about the Caverns of Time?", completion = "Neato!  A dragon of my very own!  One day I hope that I'm lucky enough to have a dragon as a friend.\n\n<Dornaa bounces up and down with joy, fiercely hugging her new toy.>\n\nThis has been the best trip ever!  I hope it never ends.", sourceObjectiveStatus = "unverified-source-field" }
quests[10963] = { id = 10963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time to Visit the Caverns", description = "In the orphanage, the old stinky priest that comes by told us stories about the Caverns of Time.  He said that it sits in the middle of time, and is really important for keeping things straight.\n\nI don't know what that means, but he said that there were dragons there that were helping to save the world!  I want to see a dragon!\n\nI think we should go there.  He said that the entrance was on the eastern edge of a great desert named Tanaris.\n\nYou could buy me a souvenir while we're there!", sourceObjective = "Take your orphan, Salandria, to stand before Zaladormu, the dragon on the dais in the middle of the Caverns of Time. Make sure to call for her if she is not present when you arrive.\n\nThen, purchase a Toy Dragon for her from the Keepers of Time Quartermaster, Alurmi, near the bottom of the entrance tunnel.", progress = "If what they say about the Caverns of Time is true, then it must be a place of great power.", completion = "Awesome!  A dragon of my very own!  Someday I plan to own a real one.\n\n<Salandria slyly eyes her new toy, the gears within her mind turning.>\n\nThis has been the best trip ever!  I hope it never ends.", sourceObjectiveStatus = "unverified-source-field" }
quests[10964] = { id = 10964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waking the Sleeper", description = "Take the ward with you and travel to Moonglade, to the Stormrage Barrow Dens. Within the southernmost of the Stormrage Barrow Dens, watched over by the dreamwardens, you will find Clintar Dreamwalker.\n\nAdminister the potion and watch over him while he wakes. He'll be extremely vulnerable as his spirit reunites with his body and he certainly won't recognize you. Declare yourself to him as soon as he comes around, {name}. He will need your help to gather the relics for the ceremony.", sourceObjective = "Use the Ward of Waking to help Clintar Dreamwalker emerge from the Emerald Dream. When he is conscious, speak to him.", progress = "<You prepare to administer the potion to the sleeping {class}.>", completion = "<The {class} emerges from his sleep, groggy and haggard looking. His gaze darts around the room in search of unseen pursuers.>\n\nMorthis?\n\nNo, you're not Morthis... Who are you, {race}, and why have you disturbed my rest?", sourceObjectiveStatus = "unverified-source-field" }
quests[10965] = { id = 10965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Mere Dream", description = "<Clintar listens as you relay Morthis' instructions, nodding, but clearly fearful.>\n\nI cannot extricate myself fully from the Emerald Dream to help you, but a fragment of my spirit will guide you in your search for the relics. Guard it well, {race}, for it is a fragile thing.\n\nThe Emerald Dream itself has become an alien, dangerous place. Its grasp on me is strong, and I will not be whole until the Emerald Dream returns to normalcy. What you see around you is but an echo of the reality inside the dream!", sourceObjective = "Protect Clintar Dreamwalker's Spirit while it gathers the relics of Aviana, then speak to Dreamwarden Lurosa.", progress = "Be quick, {race}. If these creatures escape the barrow, Clintar Dreamwalker will not be the only one in danger.", completion = "You are fortunate that Clintar was strong enough to maintain the split in his essence for so long, {name}. Few druids can manage that kind of feat while under attack in Emerald Dream. Guard the relics well!", sourceObjectiveStatus = "unverified-source-field" }
quests[10966] = { id = 10966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Orphanage", description = "Darn it all!  I guess it's time to go back to the orphanage at Shattrath City.\n\nI've had such a great time.  You're the best person in all of the worlds, {name}!  You're my big <brother/sister> now!\n\n<Dornaa's eyes begin to well up with tears.>\n\nI'm going to miss you so much!  When I grow up, I'm going to be just like you!!!", sourceObjective = "Return your ward to the Shattrath City orphanage by handing in the Draenei Orphan Whistle to Orphan Matron Mercy in the Lower City.", progress = "It is good to see you again, {class}.  I trust that you and young Dornaa had a wonderful time together?", completion = "It is good for the soul to know that there are heroes such as yourself that are willing to give of their time so selflessly.\n\nI can tell already that your time together with Dornaa has made a huge impression.  It's good for the children to have a chance to get out and see the world.\n\nHere, she told me that she wanted you to take care of one of her favorite pets, just like you took care of her.  Something to remember her by.\n\nDon't be a stranger.", sourceObjectiveStatus = "unverified-source-field" }
quests[10967] = { id = 10967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Orphanage", description = "Darn it all!  I guess it's time to go back to the orphanage at Shattrath City.\n\nI've had such a great time.  You're the best person in all of the worlds, {name}!  You're my big <brother/sister> now!\n\n<Salandria's eyes begin to well up with tears.>\n\nI'm going to miss you so much!!!", sourceObjective = "Return your ward to the Shattrath City orphanage by handing in the Blood Elf Orphan Whistle to Orphan Matron Mercy in the Lower City.", progress = "It is good to see you again, {class}.  I trust that you and young Salandria had a wonderful time together?", completion = "It is good for the soul to know that there are heroes such as yourself that are willing to give of their time so selflessly.\n\nI can tell already that your time together with Salandria has made a huge impression.  It's good for the children to have a chance to get out and see the world.\n\nHere, she told me that she wanted you to take care of one of her favorite pets, just like you took care of her.  Something to remember her by.\n\nDon't be a stranger.", sourceObjectiveStatus = "unverified-source-field" }
quests[10968] = { id = 10968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call on the Farseer", description = "I am sensing something very special about this child indeed.\n\nYou should take her to visit Farseer Nobundo, here in the Exodar.  I believe that he has been expecting the two of you.\n\nLook for Nobundo upon the highest terrace in the Crystal Hall.", sourceObjective = "Take your orphan, Dornaa, to visit Farseer Nobundo at the Crystal Hall inside of the Exodar, which is on Azuremyst Isle. Make sure to call for her if she is not present when you arrive.\n\nRemember that you can use your map inside the city.", completion = "I had hoped, but despaired she was only a figment of my imagination.  The child is amazing!\n\nIt's unheard of in this day and age that one of the draenei should exhibit such ability with the elements without any training.  She must have inherited this power from an ancient ancestor.\n\nI will send a missive to the orphan matron in Shattrath City requesting that the child be allowed to come stay with us.\n\nPlease, keep her safe until then.", sourceObjectiveStatus = "unverified-source-field" }
quests[10969] = { id = 10969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek Out Ameer", description = "It would seem that an outside force has taken an interest in the business practices of the Consortium. Five Consortium dealers have gone missing in the past two days. We have reason to believe the Ethereum are involved. If you are interested in assisting, seek out Commander Ameer at the Protectorate Watch Post.\n\nYou will find the Protectorate Watch Post directly east of here on the next island.", sourceObjective = "Seek out Commander Ameer at the Protectorate Watch Post.", completion = "Aye, it is true, but the Consortium are not the only group claiming losses.", sourceObjectiveStatus = "unverified-source-field" }
quests[10970] = { id = 10970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mission of Mercy", description = "We salvaged this prison orb on our last scouting mission into Ethereum territory. We'd have never found it had it not been for the distress signal that it was faintly emitting.\n\nWe think one of our own might be locked up in there but we have no way of opening the orb up without harming whatever is inside.\n\nWhat we know about the Ethereum is that any of their members could - at any given time - be carrying a key to unlock an orb. Retrieve one and return so that we may uncover the mysteries of this orb.", sourceObjective = "Recover the Salvaged Ethereum Prison Key for Commander Ameer at the Protectorate Watch Post in Netherstorm.", progress = "Any luck?", completion = "Stand back, {name}. This could very well be an Ethereum trap.", sourceObjectiveStatus = "unverified-source-field" }
quests[10971] = { id = 10971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ethereum Secrets", description = "<Ameer holds up a tag.>\n\nI found this prisoner I.D. tag with the remains of the fallen vanguard. I can only assume that all of their prisoners are tagged in the same manner.\n\nI'm going to start cataloguing the tags in hopes of making sense of their penal system. If in your adventures you find more Ethereum prison keys, you can use them to open the Ethereum prisons at the Ethereum Staging Grounds - directly south of here. Bring me back any and all I.D. tags that you find.", sourceObjective = "Commander Ameer at the Protectorate Watch Post in Netherstorm wants you to bring him an Ethereum Prisoner I.D. Tag.", progress = "Have you recovered any I.D tags?", completion = "It seems to be more than just an identifier. There is some sort of code written on these tags. I'm on the verge of breaking it wide open. Perhaps if I had a few more pieces.", sourceObjectiveStatus = "unverified-source-field" }
quests[10972] = { id = 10972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ethereum Prisoner I.D. Catalogue", description = "I am in need of more I.D tags, {name}. What I've discovered thus far is that this is not just a way to catalogue prisoners but it also documents locations!\n\nOnce this code is broken we'll be able to pinpoint exactly where all of our allies are held and free them with minimal hostile action received.", progress = "I am in need of more I.D. tags, {name}. What I've discovered thus far is that this is not just a way to catalogue prisoners but it also documents locations!\n\nOnce this code is broken we'll be able to pinpoint exactly where all of our allies are held and free them with minimal hostile action received.", completion = "We are close to the truth, {name}." }
quests[10973] = { id = 10973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Thousand Worlds", description = "I have cracked the code! Each tag is broken up into several segments. The front side of the tag is always the same and states: \"A Thousand Worlds...\" I am unsure as to the meaning of this phrase but it sounds insidious.\n\nOn the back side of the tag are the vital statistics. The first set of runes indicates location and the second indicates prisoner type. Furthermore, it would seem that the keys can be combined to form a special key that accesses another prison type. Now I just need more keys...", sourceObjective = "Commander Ameer at the Protectorate Watch Post in Netherstorm wants you to bring him 5 Ethereum Prison Keys.", progress = "I know it's asking a lot but think of the lives that could be saved!", completion = "<Ameer deftly combines the keys and begins to read the markings on the newly formed key tablet.>\n\n\"A thousand worlds shattered, a thousand worlds more to overcome... Such is the will of the Nexus-King.\"\n\n<Ameer turns the tablet over and begins to read from the back-side.>\n\nStasis chambers of Bash'ir?", sourceObjectiveStatus = "unverified-source-field" }
quests[10974] = { id = 10974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stasis Chambers of Bash'ir", description = "The Ethereum have a settlement on the northernmost shelf of Blade's Edge Mountains known as Bash'ir's Landing. According to the key tablet, much larger versions of the prisons are kept at Bash'ir's. It should also be noted that the Ethereum refer to those prisons as stasis chambers.\n\nThe key tablet grants access to a very specific stasis chamber at the landing known as Stasis Chamber Alpha. Take the key and investigate.\n\nMy image will be awaiting your return at Bash'ir's Landing. Speak to me there.", sourceObjective = "Use the Ethereum Key Tablet - Alpha to open Stasis Chamber Alpha at Bash'ir's Landing in Blade's Edge Mountains.\n\nReturn Evidence from Alpha to the Image of Commander Ameer at Bash'ir's Landing.", progress = "You made it! Any luck?", completion = "<The image of Commander Ameer rummages through the evidence.>\n\nIt is worse than I thought... These chambers hold ferocious beasts and creatures from many, many different worlds. They hope to one day command the beasts to do their bidding. We must destroy them all!", sourceObjectiveStatus = "unverified-source-field" }
quests[10975] = { id = 10975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purging the Chambers of Bash'ir", progress = "We're at an impasse here, {name}. The data you've collected has given us enough information to save our allies being held at the smaller prisons of Netherstorm but we must press forward and eradicate the larger Ethereum threats here at Bash'ir's Landing.\n\nJoin the battle against the Ethereum! Bring Ethereum prison keys to me and I shall forge Ethereum stasis chamber keys for you to use on the stasis chambers of Bash'ir.", completion = "There is always more work that must be done, {name}. Now seek out a stasis chamber and destroy whatever evil lurks within!" }
quests[10976] = { id = 10976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mark of the Nexus-King", description = "What I must now know is what the Ethereum have held inside the Mana-Tombs of Auchindoun.\n\nIn your battles against the beasts of the stasis chambers of Bash'ir you may run across an item known as the Mark of the Nexus-King. Should you find such an item, return it to me immediately! It is the final piece in crafting a key that will allow access to the stasis chamber inside the Mana-Tombs.", sourceObjective = "The Image of Commander Ameer at Bash'ir's Landing in the Blade's Edge Mountains wants you to bring him a Mark of the Nexus-King.", progress = "This will be your most daunting task, {name}.", completion = "At last!\n\n<Commander Ameer reads from the Mark of the Nexus-King.>\n\nTwo final prisons? I shudder to think what horrors lie in wait...", sourceObjectiveStatus = "unverified-source-field" }
quests[10977] = { id = 10977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stasis Chambers of the Mana-Tombs", description = "The Mark of the Nexus-King that you recovered has allowed me to forge a new key for the stasis chambers found inside the Mana-Tombs.\n\nAccording to the glyphs on the mark, two exist: one near the front and one near Nexus-Prince Shaffar. This key that I am about to give you will open the stasis chamber near the front.\n\nI want you to go to the Mana-Tombs of Auchindoun and open the Mana-Tombs Stasis Chamber.", sourceObjective = "The Image of Commander Ameer at Bash'ir's Landing in the Blade's Edge Mountains wants you to use the Mana-Tombs Stasis Chamber Key on the Stasis Chamber inside the Mana-Tombs of Auchindoun.\n\nThis quest may only be completed on Heroic difficulty.", progress = "I would understand if you chose not to continue, {name}.", completion = "Word has gotten back of your heroics, {name}. Haramad and I both agree that what you've done deserves a great reward.\n\nThough... Nevermind, you've done enough. I cannot in good conscience ask anything more from you.", sourceObjectiveStatus = "unverified-source-field" }
quests[10978] = { id = 10978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Morthis Whisperwing", description = "Now that the relics have been recovered, you must leave this place with all haste. Clintar risked his safety and that of the dreamwardens to help you, {name}, but now he must fully devote his attention to fighting the force that has invaded the Emerald Dream.\n\nTake the relics back to Morthis Whisperwing, along with word of what you've seen here. He may be able to help us identify just what Clintar is struggling against.", sourceObjective = "Bring the Relics of Aviana to Morthis Whisperwing at Cenarion Refuge in Zangarmarsh.", progress = "Did Clintar help you recover the relics?", completion = "<Morthis accepts the relics from you as you describe your experiences in the barrow dens.>\n\nThis is most troubling news, {name}. There have been any number of strange disturbances in the Emerald Dream, but I can't remember any mention of outside forces tampering with it. Are you certain that's what Clintar believes?", sourceObjectiveStatus = "unverified-source-field" }
quests[10979] = { id = 10979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Evergrove", description = "Are you certain you saw a raven in the barrow den?\n\nThis is a troubling development. There's little we can do to help Clintar and the dreamwardens directly, but if we can learn more about what's threatening the Emerald Dream, we may be able to stop it.\n\nWe've been learning about the resurgence in an ancient arakkoa cult in Blade's Edge -- one that venerates a raven god. Go to the Evergrove and find Arthorn Windsong. There may be a connection between what's happening there and in the Emerald Dream!", sourceObjective = "Speak with Arthorn Windsong at the Evergrove in Blade's Edge Mountains.", completion = "<Arthorn listens as you explain that Morthis Whisperwing sent you to investigate a connection between the cult of the raven god and strange happenings in Moonglade. Though shocked at the news, she seems more disappointed at the message's nature.>\n\nOh my...\n\nI've been helping Timeon with his research on the raven cult, but we never imagined its patron had any reach beyond Blade's Edge!", sourceObjectiveStatus = "unverified-source-field" }
quests[10980] = { id = 10980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Book of the Raven", description = "From what you've told me, Morthis's suspicions seem plausible, but we need confirmation.\n\nIn his research, Timeon has uncovered clues that a \"book of the raven\" served as an ancient scripture to the cult.\n\nThe arakkoa spirits will not reveal themselves to your eyes. Take this stone with you to the high peaks in the western part of Blade's Edge, to the south of Raven's Wood, obtain an aether ray eye, and combine them to augment your sight. Search for the ghost Timeon identified as Sai'kkal the Elder.", sourceObjective = "Use an Aether Ray Eye with your Seer's Stone to reveal the raven cult ghosts. Search the Vortex Pinnacle for the spirit of Sai'kkal the Elder and question him about the book of the raven, then return to Arthorn Windsong.", progress = "<Arthorn looks at you hopefully.>\n\nWere you able to track down any information about the book?", completion = "Isn't it amazing that even among arakkoa, the cultists were considered heretics? That the traditional priests hated them enough to destroy their holy text is incredible! We must get our hands on that book, {name}.\n\nIt's the key to unraveling the mystery of the raven god and preventing him from taking over the Emerald Dream.\n\nPerhaps Morthis will finally agree to take me as a student if we succeed!", sourceObjectiveStatus = "unverified-source-field" }
quests[10981] = { id = 10981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nexus-Prince Shaffar's Personal Chamber", progress = "Only the most steadfast and battle-hardened of adventurers will take me up on this offer, {name}. Should you wish to face the horrors of the second stasis chamber in the Mana-Tombs, I am able to synthesize a key. Bring me a mark of the Nexus-King and I will make it so.", completion = "As promised, here is the key to Shaffar's personal stasis chamber." }
quests[10982] = { id = 10982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of Haramad", sourceObjective = "You have done much for the Protectorate and the Consortium, {name}. It is only fitting, then, that the first of our new keys goes to you. With this key you will be able to open Shaffar's personal stasis chamber at any time without having expended the key itself.\n\n\n\nIt is permanent and will be with you forever.", sourceObjectiveStatus = "unverified-source-field" }
quests[10983] = { id = 10983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mog'dorg the Wizened", description = "Mog'dorg wise!  Him send Grok to city, look for help.  Bloodmaul clan need help.\n\nMog'dorg say, send powerful little ones to him at Blade's Edge Mountains.  Him stand on tower at Circle of Blood.  Mog'dorg wise!", sourceObjective = "Visit Mog'dorg the Wizened atop one of the towers just outside the Circle of Blood in the Blade's Edge Mountains.", completion = "Grok said that I am wise?  I don't know about that.\n\nPerhaps it is because I am the only one in my clan that is truly trying to save us from annihilation by the Bladespire clan, and Gruul and his sons, who are backing them.\n\nI hope that you have come to deliver us from certain doom, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10984] = { id = 10984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with the Ogre", description = "<V'eru's voice fills your mind with crystalline tone and clarity.>\n\nThere is an ogre down in the Lower City, pleading for the assistance of passersby.  They have all turned a deaf ear upon his plight.\n\nDo you think you might aid him?\n\nHis name is Grok, and he is sitting near the merchants to the southeast.\n\nThank you, {name}.", sourceObjective = "Speak with the Ogre, Grok, in the Lower City section of Shattrath City.", completion = "You help Grok?  Grok need help!  Bloodmaul clan need help!", sourceObjectiveStatus = "unverified-source-field" }
quests[10985] = { id = 10985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Distraction for Akama", description = "<Xi'ri pulses with lights as the Aldor and Scryer forces around him respond to his orders.  Xi'ri's army is ready to push Illidan's forces back and create a distraction for Akama.  The naaru awaits your request to begin the attack.>", sourceObjective = "Ensure that Akama and Maiev enter the Black Temple in Shadowmoon Valley after Xi'ri's forces create a distraction.", progress = "<Xi'ri acknowledges your presence.>", completion = "<Xi'ri pulses with energy as you feel an object materialize in your hands.  It is the medallion you gave to A'dal on Akama's behalf, its power augmented by the naaru's magic.  The Sha'tar have entrusted you with the Medallion of Karabor, and with it access to the Black Temple.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10986] = { id = 10986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes in the Sky", description = "Locating the pieces of the Book of the Raven, if they survive at all, is going to be difficult. Our best hope is to use a keener pair of eyes than your own.\n\nDown in western Nagrand, on the eastern lip of the Twilight Ridge, Watcher Elaira studies the various bird species that make their home there. Visit her and see if she can help you harness avian sight to gather the pieces of the Book of the Raven.", sourceObjective = "Speak with Watcher Elaira at the Twilight Ridge in Nagrand.", completion = "<Elaira listens as you describe your search for the Book of the Raven and Arthorn's suggestion to use birds to locate the missing pieces of the tablet.>\n\nIt's an excellent idea and Nagrand is teeming with candidates, but which one to use?", sourceObjectiveStatus = "unverified-source-field" }
quests[10987] = { id = 10987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Catch A Sparrowhawk", description = "The wild sparrowhawks of Nagrand have the keenest sight of all the predatory birds here. But, because of their size, they've been pushed out of most areas by the larger windrocs.\n\nMost of the sparrowhawks nest here, on the Twilight Ridge. If you can catch one, I'll train it to spot the pieces of your buried tablet.\n\nIt's going to be difficult, though. The sparrowhawks are very skittish and will flee at your approach. I'd suggest cornering one or prowling to get close enough to cast your net.", sourceObjective = "Use the Sparrowhawk Net to capture a Wild Sparrowhawk and bring it to Watcher Elaira on the Twilight Ridge.", progress = "Did you catch one of the sparrowhawks?", completion = "Well done! I'm still in the process of getting the hawks to trust me, but I know enough about them to train this one for your needs.", sourceObjectiveStatus = "unverified-source-field" }
quests[10988] = { id = 10988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Raven Stones", description = "I've trained your sparrowhawk to respond to a specific whistle. When it hears the sound, the bird will fly to you and guide you to the location of the nearest tablet fragment. Arthorn sent word that the fragments you're looking for are buried in the Skettis area of southeastern Terokkar Forest, so the bird will wait for you there.\n\nWhen you've gathered all the stones, return the whistle to Arthorn and she will see to the animal's care and release.\n\nConvey my greetings to Arthorn when you see her.", sourceObjective = "Gather 8 Raven Stones from Skettis and bring them to Arthorn Windsong at Evergrove in Blade's Edge Mountains.", progress = "Did you recover enough of the Book of the Raven for me to reconstruct it?", completion = "<Arthorn accepts the fragments of the Book of the Raven from you and begins piecing them together.>\n\nSome of the characters have been worn away, but I should be able to make out most of this...", sourceObjectiveStatus = "unverified-source-field" }
quests[10989] = { id = 10989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mog'dorg the Wizened", description = "Mog'dorg the Wizened waits for you at top of da tower.  He tells me to look for a {race} {class} just like you.  You go speak with him about smart things.\n\nGo now, but don't tell no one.  It's a secret!", sourceObjective = "Speak with Mog'dorg the Wizened atop the tower where Chort is standing, just outside the Circle of Blood in the Blade's Edge Mountains.", completion = "Finally, Chort has sent me someone who looks like they might be able to help.  I am trying to save the Bloodmaul from annihilation by the Bladespire clan, and Gruul's sons, who are backing them.\n\nI trust that you will be the one to aid our secret society and deliver us into freedom.", sourceObjectiveStatus = "unverified-source-field" }
quests[10990] = { id = 10990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eagle's Essence", description = "The Book of the Raven tells us the raven's followers captured and bound the spirits of his rivals within stone shrines. A guardian was set to watch over each, lest the raven's enemies attempt to free them.\n\nThe first of the shrines is the eagle's, found in the hills to the south of Lake Jorune and west of Stonebreaker Hold in Terokkar Forest.\n\nThe tablet says that the eagle fought valiantly, but was overcome by a swarm of enemies. The armor and endurance of your bear form is well-suited to this fight.", sourceObjective = "Defeat the Guardian of the Eagle and obtain the Essence of the Eagle. Use Arthorn's Sparrowhawk Whistle to call Arthorn's Sparrowhawk to relay news of your success.\n\nIf you lose Arthorn's Sparrowhawk Whistle, return to Arthorn Windsong at the Evergrove for a replacement.", progress = "<The sparrowhawk seems to speak with Arthorn's voice.>\n\nDid you succeed in freeing the essence of the eagle spirit?", completion = "<Arthorn seems to feel the power in the recovered essence through the sparrowhawk's senses.>\n\nEven after thousands of years of captivity, the eagle's power remains strong. If the other essences are as strong as the eagle's, the raven god will be right to fear you.", sourceObjectiveStatus = "unverified-source-field" }
quests[10991] = { id = 10991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Falcon's Essence", description = "<The bird speaks with Arthorn's voice.>\n\nThe second spirit bound by the raven's followers was the falcon.\n\nIt was subdued and imprisoned close to Skettis as a reminder to the raven-priests when they held power.\n\nOn the shores of Lake Ere'Noru, to the northwest of Skettis, you'll find the falcon's shrine.\n\nTo overcome the falcon's guardian, you'll need to use the falcon's strengths to your advantage. Use the speed and grace of your cat form to defeat the guardian before it reaches full strength!", sourceObjective = "Defeat the Guardian of the Falcon, obtain the Essence of the Falcon. Use Arthorn's Sparrowhawk Whistle to call Arthorn's Sparrowhawk to relay news of your success.\n\nIf you lose Arthorn's Sparrowhawk Whistle, return to Arthorn Windsong at the Evergrove for a replacement.", progress = "<Once again, Arthorn's voice issues from the sparrowhawk.>\n\nDo you have the falcon's essence?", completion = "<The sparrowhawk dutifully conveys Arthorn's words.>\n\nWell done, {name}. I'd feared that the falcon's prison had been destroyed in the explosion of Auchindoun. We're almost prepared to confront Anzu, {name}. I'd love to go with you, to be there when this self-styled \"god\" is cast back into the pit that spawned him!", sourceObjectiveStatus = "unverified-source-field" }
quests[10992] = { id = 10992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hawk's Essence", description = "<Arthorn's voice addresses you.>\n\nThe last, and strongest, of the spirits spoken of in the Book of the Raven is that of the hawk. It was imprisoned far from Skettis, in a shrine on a remote island southeast of Auchindoun.\n\nI believe this description best matches the island we know as Sorrow Wing Point.\n\nThe tablet describes the hawk's guardian as nearly invulnerable to the bird's claws. Forsake physical attacks and call down the fury of the stars to defeat this foe. Do not repeat the hawk's mistake.", sourceObjective = "Defeat the Guardian of the Hawk and bring the Essence of the Hawk to Arthorn Windsong at the Evergrove.", progress = "Did you overcome the hawk's guardian and win its essence?", completion = "Now that we have all the essences, Morthis Whisperwing must find a way to combine them into an amulet that you'll be able to use to challenge the raven god, draw him out of the Emerald Dream and defeat him. I'll be sending him my notes on the spirits with the hope that he'll realize the value of my insight.\n\nEach of the spirits has blessed a charm I've prepared for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[10993] = { id = 10993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Cenarion Refuge", description = "Bring the essences to Morthis Whisperwing, along with word of our findings about the raven god.\n\nMorthis will know best how to use the essences and information in drawing Anzu out into the open. Make your way to him quickly, for there's no telling how long Clintar and the dreamwardens can withstand the raven's assault!\n\n<Arthorn grabs your arm before you turn to leave>.\n\nPlease, {name}, tell Morthis how much of a help I've been to you. I fear he will not see my hand in this work!", sourceObjective = "Bring Arthorn's Package to Morthis Whisperwing at Cenarion Refuge.", progress = "I've been waiting for word from Arthorn. What have you discovered?", completion = "<Morthis accepts the package, opens it to discover Arthorn's notes, and reads over them without commenting on the author.>\n\nOn one level, I'm relieved to finally know the identity of our enemy, but this Anzu is a being of considerable power. Knowing the nature and the name of your adversary is vital, but we are not yet ready to face him.", sourceObjectiveStatus = "unverified-source-field" }
quests[10994] = { id = 10994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing the Moonstone", description = "If the essences are combined within a rare gemstone such as a Southfury moonstone, you'll be able to release them when you're prepared to challenge Anzu.\n\nThe only problem is that Southfury moonstones are only found on the Azshara side of the river, on the cliffs near the river's source.\n\nTragedy befell the last night elf party that sought the stone. Their boat is still anchored in the river near where they sighted the moonstone. Keep your eyes open and approach the site by land from the Azshara side.", sourceObjective = "Bring a Southfury Moonstone to Morthis Whisperwing at the Cenarion Refuge.", progress = "You look like you've been through quite an ordeal. Was the moonstone really that hard to find?", completion = "<Morthis seems torn, at once desiring to laugh at your story, and mindful of how close you came to losing the moonstone. He settles for staring at the glowing stone.>\n\nI'll get to work on infusing it with the bird spirit essences. Soon, you'll be prepared to challenge our enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[10995] = { id = 10995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grulloc Has Two Skulls", description = "To the east, at the terminus of Dragons' End, is the Cursed Hollow.  Therein, Grulloc, son of Gruul, plots his dimwitted schemes.\n\nI heard that one of his possessions was stolen from him through trickery.  Was that you?  Unfortunate that he was not slain in the process.\n\nIf we are to regain our freedom, I would have you take his most prized possession, a dragon skull from when he rejoiced in his father's slaying of the black dragonflight.  The only way you'll get the skull is to vanquish him.", sourceObjective = "Collect Grulloc's Dragon Skull.", progress = "Is Grulloc no more?", completion = "Indeed, it must have been a difficult struggle, {class}.  I feel greatly relieved now that he will not be breathing down our necks here.\n\nI will send this skull down to Chort for safekeeping.  I'm beginning to think that with your help, we might just pull this off.", sourceObjectiveStatus = "unverified-source-field" }
quests[10996] = { id = 10996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maggoc's Treasure Chest", description = "On the Razor Ridge, above and to the southeast, Maggoc patrols.  His father assigned him as the warden of the eastern mountain range, and he revels in terrorizing any creature that gets in his way.\n\nAs a son of Gruul, he must be done away with if my clan is to survive.  That's where you come in.\n\nMaggoc carries a treasure chest with him at all times.  Prove to me that he has been slain by bringing me his precious chest.  Feel free to keep whatever you find within it.", sourceObjective = "Collect Maggoc's Treasure Chest.", progress = "Do you have the chest?", completion = "You say it was empty?  Unfortunate, but you can see the mindless brutality that we're up against.\n\nWith the fall of Maggoc, we are one step closer to realizing my dream of a home for the ogres where we can determine our own destiny.", sourceObjectiveStatus = "unverified-source-field" }
quests[10997] = { id = 10997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Even Gronn Have Standards", description = "Are you familiar with Shattrath City, {class}?  Above it to the northwest is a place called the Barrier Hills, which you can only get to upon a flying mount.\n\nOne of Gruul's sons, Slaag, exiled himself and took control of the Gordunni ogres that reside there.  Even at such a distance, we cannot afford to leave him in peace, lest he return when the rest of his brothers have been slain.\n\n{name}, you must travel there, and bring back his standard as proof that he has been dealt with.", sourceObjective = "Collect Slaag's Standard.", progress = "Do you return with Slaag's standard in hand?", completion = "What a relief that Slaag is gone.  No longer will we be threatened by the looming specter of his return!\n\nIf you do not mind, I will take the standard as a symbol of hope for all of the ogres of the mountains.\n\nThank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10998] = { id = 10998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grim(oire) Business", description = "There is one more gronn to be slain: Skulloc Soulgrinder. He keeps himself hidden away, but there is a way to coax him forth.\n\nHe was trained by an ogre warlock known as Vim'gol the Vile, whose grimoire you must retrieve!\n\nVim'gol must be summoned by standing within a fire ring at his circle. Find Vim'gol's Circle in the mountains, to the northeast, near the Broken Wilds.\n\n{name}, if you hear Vim'gol talk about growing bigger, get people back into each of the five fire rings to interrupt his casting!", sourceObjective = "Collect Vim'gol's Vile Grimoire.", progress = "Have you summoned forth Vim'gol the Vile and taken the grimoire from his dead clutches?", completion = "I hesitate to even touch such a tainted thing of evil.  Yet read it we must if we are to glean what knowledge it contains and bring forth Skulloc from his hiding place.", sourceObjectiveStatus = "unverified-source-field" }
quests[10999] = { id = 10999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Shot, One Kill", description = "Bring me 8 trogg stone teeth." }
quests[11000] = { id = 11000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Soulgrinder", description = "The grimoire is the key to Skulloc's downfall.\n\nRead aloud from the book at Soulgrinder's Barrow to initiate the ritual.  An object known as the Soulgrinder will appear, as well as Skulloc's ghostly victims, who will try to destroy it.  You must keep them from doing so long enough to force Skulloc fully into the world.\n\nFind the barrow by heading north through the Daggermaw Canyon on the other side of the Circle of Blood.  It is on the right side before Gruul's Lair.\n\nBring back Skulloc's soul.", sourceObjective = "Collect Skulloc's Soul.", progress = "Have you taken Skulloc's soul yet?", completion = "It is over then.  You have freed us from the shackles of our enslavement to the Sons of Gruul.  You have given the Bloodmaul Clan a reprieve from certain extinction.\n\nWords cannot describe the extent of the debt that ALL of the ogres of the Blade's Edge Mountains, Bloodmaul and Bladespire alike, owe you, {name}.\n\nLook down, even now the ogres gather to pay you tribute.  Let Gruul and his puppet, the old king, Maulgar, cower within their lair.  Go to the ogres below as our new king!", sourceObjectiveStatus = "unverified-source-field" }
quests[11001] = { id = 11001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vanquish the Raven God", description = "We must waste no time in dealing with the raven god. You must take the essence-infused moonstone to a place of great power in order to lure the god from the relative safety of the Emerald Dream.\n\nDescend into the Sethekk Halls and set the moonstone in the clutches of the raven's claw. You'll find it in the chamber before the talon king's hall.\n\nAnzu must be made believe that his followers have gathered to welcome him back into the world. Once he has manifested, show him no mercy!", sourceObjective = "Slay the Raven God and return to Morthis Whisperwing at Cenarion Refuge.\n\nThis quest must be completed in Heroic dungeon difficulty.", progress = "What news from Sethekk Halls? Have you defeated Anzu?", completion = "It's good to see you again, {name}. Your triumph over the raven god counts for far more than any test or rite of passage that I might set for you.\n\nYou have truly proven yourself worthy of the knowledge guarded by the Druids of the Talon for countless generations.", sourceObjectiveStatus = "unverified-source-field" }
quests[11002] = { id = 11002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of Magtheridon", description = "The source of Illidan Stormrage's fel orc army has been vanquished. The manufactory halts production of its grim product - at least for now. All that remains are a few trinkets and this severed head - a fitting trophy for a hero of the Alliance.\n\nReturn Magtheridon's head to Danath Trollbane at Honor Hold.", sourceObjective = "Return Magtheridon's Head to Force Commander Danath Trollbane at Honor Hold in Hellfire Peninsula.", progress = "For the first time - in as long as I can remember - there is silence.", completion = "This defeat is not only a blow to Illidan, {name}. The Legion too reels... A pit lord commander has been defeated. The siege of Hellfire Citadel now holds no purpose for the Burning Legion. All of their efforts will undoubtedly be turned upon the Black Temple.\n\nRedemption comes for Illidan... and soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[11003] = { id = 11003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of Magtheridon", description = "The source of Illidan Stormrage's fel orc army has been vanquished. The manufactory halts production of its grim product - at least for now. All that remains are a few trinkets and this severed head - a fitting trophy for a hero of the Horde.\n\nReturn Magtheridon's head to Nazgrel at Thrallmar.", sourceObjective = "Return Magtheridon's Head to Nazgrel at Thrallmar in Hellfire Peninsula.", progress = "For the first time - in as long as I can remember - there is silence.", completion = "This defeat is not only a blow to Illidan, {name}. The Legion too reels... A pit lord commander has been defeated. The siege of Hellfire Citadel now holds no purpose for the Burning Legion. All of their efforts will undoubtedly be turned upon the Black Temple.\n\nRedemption comes for Illidan... and soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[11004] = { id = 11004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "World of Shadows", description = "Sky Commander Adaris was seriously injured during a Skettis incursion.  He's been in and out of consciousness since.\n\nI fear he has succumbed to a feverish delirium.  During brief lucid moments he demands that I prepare an elixir made from shadow dust carried by the arakkoa.  He seems to believe it will allow him to see into a \"world of shadows\" where the arakkoa's true leaders dwell.\n\nI do not believe this nonsense for a second, but I fear he won't rest until I obtain such an elixir.  Will you help?", sourceObjective = "Severin wants you to venture into Skettis and retrieve 6 Shadow Dusts from the arakkoa that dwell there.", progress = "Have you obtained the dust, {name}?", completion = "I thank you, {name}.  I will administer a small amount to the commander... to humor him.  You can keep the rest, perhaps you'll find a use for it.", sourceObjectiveStatus = "unverified-source-field" }
quests[11005] = { id = 11005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Talonpriests", description = "Thank you for paying heed to my fevered rants.  All along we had been trying to identify and destroy the Skettis chain of command; we had learned of three clerics known as the talonpriests, but we'd never seen them with our own two eyes.  Now we know why.\n\nTalk to Severin to obtain more of the elixir he discovered.  Use the elixir to find and kill the three talonpriests: Ishaal, Skizzik and Zellek.  They're rumored to dwell in Veil Ala'rak, near the eastern shore of Blackwind Lake.", sourceObjective = "Obtain an Elixir of Shadows from Severin and use it to find and slay Talonpriest Ishaal, Talonpriest Skizzik and Talonpriest Zellek in Skettis. Return to Commander Adaris after completing this task.", progress = "Is the deed done, {name}?  I'd kill those blasted birdmen myself if it weren't for my injuries.", completion = "You've done well, {name}.  You've dealt a tremendous blow to the enemy by slaying the talonpriests.", sourceObjectiveStatus = "unverified-source-field" }
quests[11006] = { id = 11006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Shadow Dust", progress = "It looks like the commander was not delirious after all.  Bring me more dust and I'll prepare another elixir for you.", completion = "Keep bringing the dust to me.  I'll prepare as many elixirs as you need.\n\nCommander's orders." }
quests[11007] = { id = 11007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kael'thas and the Verdant Sphere", description = "The air around you hums - a gentle hum. The naaru are aware of your victory. Perhaps they are the reason you were compelled to pick up this sphere from the still-twitching remains of Kael'thas Sunstrider. What secrets could it hold?\n\nPerhaps A'dal in Shattrath City could make sense of the item.", sourceObjective = "Take the Verdant Sphere to A'dal in Shattrath City.", progress = "You heard my call? Yes...", completion = "<A'dal's thoughts intermingle with your own.>\n\nThe sphere... Strange. Did you know that he lived? Yes. It is here - in the sphere itself. Maimed for certain. He calls to a higher power now. No, not Illidan.\n\nHigher.\n\nKil'jaeden the Deceiver comes...\n\nNot here...\n\n<A'dal points your mind elsewhere.>\n\nAzeroth. Unknown.\n\nRest. Your brothers and sisters will retake Tempest Keep now.\n\n<A'dal hums a song of battle.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11008] = { id = 11008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fires Over Skettis", description = "You think you have what it takes to be part of the Skyguard?  We'll have to see how you handle yerself in the air.\n\nThe arakkoa are breeding a gargantuan variety of their attack pets and are using it against our scouts.  I want you to take these blasting charges and use them to destroy hatcheries above the arakkoa's dwellings.  Avoid the monstrous kaliri guarding the hatcheries.  They'll knock you off your mount before you know what hit you.", sourceObjective = "Seek out Monstrous Kaliri Eggs on the tops of Skettis dwellings and use the Skyguard Blasting Charges on them. Return to Sky Sergeant Doryn.", progress = "Did you finish your assignment yet?", completion = "Excellent job, {name}!  That'll show those bird men the meaning of air superiority!", sourceObjectiveStatus = "unverified-source-field" }
quests[11009] = { id = 11009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogre Heaven", description = "Now that you have delivered us from bondage, we can begin the process of reunifying the clans.  This will take some time; old grudges are difficult to overcome.\n\nBut more pressing, you must go to Ogri'la in the heavens above to the west.  You must defend it, and us, from those forces above that the gronn used to protect us from: ethereals, demons, and worst of all, the black dragonflight.\n\nWhen you find ogre heaven, seek out the wisdom of Chu'a'lor on how best to proceed.", sourceObjective = "Speak with Chu'a'lor at Ogri'la in the Blade's Edge Mountains.", completion = "Mog'dorg sent a message ahead, saying that I should expect you.  I am glad that you came.\n\nWith the Sons of Gruul destroyed, it is only a matter of time - a short amount at that - before the various inhabitants of this mountain terrace, and the one to the north, decide to prey upon our ogre brothers down below.\n\nI trust that you will help us to prevent that, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11010] = { id = 11010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombing Run", description = "You have a flying mount... so what!  You think you have what it takes to use it properly?\n\nForge Camp: Wrath and Forge Camp: Terror, to the north and south, are a major pain in my backside, as well as being a threat to peaceful Ogri'la.  With all of those fel cannons shooting down the Skyguard left and right, we can't get through there to take care of business.\n\nYou want to prove yourself?  Take these bombs and knock out their ammo stacks.  Just don't let them shoot you down, too!", sourceObjective = "Use the Skyguard Bombs to destroy 15 Fel Cannonball Stacks.", progress = "You take out their stacks of fel cannonballs yet?", completion = "Well, well, well, I guess you had it in you after all.  Good work.  Maybe Old Man Keller was wrong about you after all.\n\n<Sky Sergeant Vanderlip smirks.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11011] = { id = 11011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eternal Vigilance", description = "Your defeat of Anzu, the raven god, is truly a remarkable accomplishment. He may not abandon his quest to return to Outland, I fear.\n\nAs long as he has followers here, he will attempt to rise again. Keep the essence-infused moonstone with you in case we have not heard the last of Anzu.", sourceObjective = "Speak with Morthis Whisperwing to receive an Essence-Infused Moonstone.", completion = "Keep the moonstone with you, {name}. If you suspect that Anzu is gathering his strength to attempt another return to this world, use it to defeat him once again.", sourceObjectiveStatus = "unverified-source-field" }
quests[11012] = { id = 11012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Oath of the Netherwing", sourceObjective = "Our lands are lost. Our children stolen in the night, forced into slavery - or worse...\n\n<Mordenai's voice tenses.>\n\nThe time is now, my ally. The time to retake what was once ours has come! You have proven yourself a capable combatant and compassionate soul.\n\nWill you swear to assist the Netherwing Dragonflight in retaking our lands and rebuilding our homes? Will you swear to watch over the flight and allow the bloodline to be born anew? Swear this and let us battle for our home and our loved ones!", sourceObjectiveStatus = "unverified-source-field" }
quests[11013] = { id = 11013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Service of the Illidari", description = "Netherwing Ledge... What was once a bastion of sanctuary for the Netherwing is now home to the Dragonmaw. While the orcs may have control of our territory, our magic there is still strong. Strong enough to cloak your true identity and allow you to infiltrate the ranks of Dragonmaw.\n\nI have prepared this letter for you to present to their leader, Overlord Mor'ghor. Fly headlong into the maw of our enemy and seek out Dragonmaw Base Camp to start your new life as a fel orc of Illidan Stormrage.", sourceObjective = "Travel to Netherwing Ledge and deliver the Illidari Service Papers to Overlord Mor'ghor at Dragonmaw Base Camp.", progress = "<Mor'ghor grunts.>\n\nYou're late...", completion = "<Mor'ghor reads the letter and laughs.>\n\nA death knight? You couldn't shine the boots of a death knight, maggot.\n\n<Mor'ghor looks you over.>\n\nBut yes... You might be able to work your way up to peon. At the worst, I'll toss you into the pit and leave you to die...", sourceObjectiveStatus = "unverified-source-field" }
